(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c50"]=[{"id":"00002029","register_sub_id":"101","register_pk":"103019","name":"廣野家住宅主屋","kana":"ひろのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市寺家町254","lat":36.76458704,"lng":137.33713313,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0056","desc":"廣野家は旧北陸街道に直交する中川沿いの角地に位置する。主屋は大正３年に深井氏が建設し，昭和初年頃に廣野氏が取得した。入母屋造・妻入・２階建で，外観は繊細な出格子と深い軒が特徴的であり，室内は数寄屋風の書院造で細部まで凝ったつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002029"},{"id":"00012728","register_sub_id":"101","register_pk":"367631","name":"芳里家住宅主屋","kana":"ほりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県砺波市堀内50-1","lat":36.65011583,"lng":136.96864583,"geo_status":"db","era":"明治14年頃／明治43年・平成25年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋造、瓦葺、建築面積345㎡","structure_material":"木造平屋造","registered":"2019.03.29(平成31.03.29)","register_no":"16 － 143","desc":"市北部の田園地帯にある農家で、主屋は敷地中央に東面して建つ。間口の広い切妻造桟瓦葺妻入の平屋建で、正面の妻にアズマダチの意匠を表す。北に土間、南に4列に室を配し、南側面西端に角屋で座敷を設ける。砺波平野の農村景観のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012728"},{"id":"00012729","register_sub_id":"101","register_pk":"367632","name":"芳里家住宅土蔵","kana":"ほりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県砺波市堀内50-1","lat":36.65011583,"lng":136.96864583,"geo_status":"db","era":"明治6年／昭和16年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"16 － 144","desc":"主屋背面に建つ家財蔵。置屋根式の切妻造桟瓦葺で、東面中央に扉口を開く。外壁は漆喰塗で腰モルタル洗出し仕上とし、軒に鉢巻二段を廻す。内部は上下階とも一室で、床板敷、壁横板張、垂木小屋組とする。砺波平野の伝統的な農家の構成に欠かせない附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012729"},{"id":"00012730","register_sub_id":"101","register_pk":"367633","name":"芳里家住宅長屋門","kana":"ほりけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県砺波市堀内50-1","lat":36.65011583,"lng":136.96864583,"geo_status":"db","era":"明治43年頃／平成28年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"16 － 145","desc":"敷地東面の中央に建つ。切妻造桟瓦葺の平屋建で、中央南寄りに開く門口の北側に2室を配し、門口内の南面と西面北半に各出入口を設ける。門口は木太い鏡柱と冠木を組んで両開き板扉を備え、冠木上の出梁で軒桁を受ける。旧家の風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012730"},{"id":"00009449","register_sub_id":"101","register_pk":"194242","name":"丸谷家住宅（旧津野家住宅）主屋","kana":"まるやけじゅうたく（きゅうつのけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市吉久2-2618","lat":36.77925819,"lng":137.05519414,"geo_status":"db","era":"明治中期／大正期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積143㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"16 － 0091","desc":"旧放生津往来に面し、木造平屋一部二階建、切妻造桟瓦葺。正面外観は繊細な格子と簓子下見板張で構成し、内部は、ゲンカンの奥に天井を吹抜けとするオイを配し、南側の増築部を座敷とする。建ちの低い外観で、舟運で栄えた吉久における町家の古式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009449"},{"id":"00009450","register_sub_id":"101","register_pk":"194243","name":"丸谷家住宅（旧津野家住宅）土蔵","kana":"まるやけじゅうたく（きゅうつのけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県高岡市吉久2-2618","lat":36.77935408,"lng":137.05502972,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"16 － 0092","desc":"主屋後方に庭を挟んで南北棟で建ち、廊下で接続する。土蔵造二階建、桁行四・六メートル梁間四・〇メートル、切妻造桟瓦葺で、東面に蔵前を設け、外壁は下見板張及び簓子下見板張とする。東面出入口の土戸には、家紋のほか、梅に鶴、波に亀の鏝絵を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009450"},{"id":"00015171","register_sub_id":"101","register_pk":"530595","name":"山崎家住宅主屋","kana":"やまざきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県中新川郡上市町浅生字中坪18","lat":36.66000278,"lng":137.40586111,"geo_status":"db","era":"明治20年 ／昭和28年頃・同35年頃改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積246㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"16 - 0172","desc":"上市町の市街地南東の山間に位置し、敷地中央に西面して建つ農家の主屋。桁行一一間、梁間五間の二階建切妻造桟瓦葺。内部は五列１０室に部屋を配し、十八畳の広間は成の高い差鴨居を四周に廻し、上部に井桁状に組んだ梁組を現す、豪壮なつくりの大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015171"},{"id":"00015172","register_sub_id":"101","register_pk":"530596","name":"山崎家住宅土蔵","kana":"やまざきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県中新川郡上市町浅生字中坪18","lat":36.6598,"lng":137.40589167,"geo_status":"db","era":"明治21年","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"16 - 0173","desc":"主屋の南に位置し、北面して建つ米蔵兼家財蔵。桁行三間半梁間二間半、置屋根形式の桟瓦葺、戸前付の土蔵造二階建。各階二室で一階を土間、二階を板敷。外壁白漆喰塗で鉢巻を廻らし、腰黒漆喰塗、妻に家紋等を付した重厚な外観で、旧家の屋敷構を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015172"},{"id":"00014591","register_sub_id":"101","register_pk":"515133","name":"山田家住宅蔵","kana":"やまだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市福野字新町1363-3他","lat":36.59093611,"lng":136.92261111,"geo_status":"db","era":"明治前期／大正後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0164","desc":"福野の新町通りに面して酒造業を営んだ旧家の家財蔵。二階建切妻造平入、東の蔵と西の納屋を一体の土蔵造東西棟とし、桟瓦葺置屋根を架け、北に板敷の下屋を付して戸前とする。蔵と納屋の内部は各階一室。漆喰塗の重厚な外観が地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014591"},{"id":"00014592","register_sub_id":"101","register_pk":"515134","name":"山田家住宅倉庫（旧詩百篇酒造壜倉）","kana":"やまだけじゅうたくそうこ（きゅうしひゃっぺんしゅぞうびんぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市福野字新町1363-3他","lat":36.59117222,"lng":136.92266667,"geo_status":"db","era":"明治中期／昭和39年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0165","desc":"福野の新町通りに面して酒造業を営んだ旧家の瓶詰の倉。二階建切妻造平入桟瓦葺の東西棟で南に下屋を付す。真壁造で内部一階は土間の東西二室とし、西室中央に独立柱を立て、南西に階段を配す。二階は二室の板敷。土間には釜を残し、酒造業の様相を示す壜倉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014592"},{"id":"00014593","register_sub_id":"101","register_pk":"515135","name":"山田家住宅門及び塀","kana":"やまだけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県南砺市福野字新町1363-28他","lat":36.59084722,"lng":136.92278889,"geo_status":"db","era":"昭和39年頃","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長32m","structure_material":"門 木造","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0166","desc":"福野の新町通りに面して酒造業を営んだ旧家の門及び塀で、敷地南東辺に沿って矩折に延びる。南辺東寄りに開く門は道よりやや奥まって建つ切妻造桟瓦葺の腕木門で門口に格子戸を入れる。塀は縦板張とし門両脇に連続し、通りに面して旧家の屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014593"},{"id":"00014590","register_sub_id":"101","register_pk":"515132","name":"山田家住宅洋館","kana":"やまだけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県南砺市福野字新町1363-3他","lat":36.59103333,"lng":136.922625,"geo_status":"db","era":"昭和4年／昭和13年・同39年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡、渡廊下付","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0163","desc":"福野の新町通りに芸術家山田正廣の創作兼療養のため建てられた洋館。敷地西半に建つ二階建切妻造桟瓦葺で設計は吉田鉄郎。外壁は下見板張で東に出窓を設ける。内部西辺に階段を設け、二階は洋間の画室と広縁付座敷を配す。吉田鉄郎の和洋折衷住宅として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014590"},{"id":"00011666","register_sub_id":"101","register_pk":"210682","name":"有隣庵（旧土肥家住宅）主屋","kana":"ゆうりんあん（きゅうどいけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県滑川市瀬羽町1848","lat":36.763092,"lng":137.3354,"geo_status":"db","era":"慶応3年（1867）","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0122","desc":"旧北陸街道に北面する当地最古の町家。正面五間の切妻造平入、桟瓦葺で、庇は板葺。左勝手に土間を通し、床上部は街路側のミセ以外は二列構成とし、オイをワクノウチとする。正面二階両脇にコワキと呼ばれる袖壁を立ち上げるなど、地域の景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011666"},{"id":"00014595","register_sub_id":"101","register_pk":"515137","name":"吉田家住宅石蔵","kana":"よしだけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市二口字馬渡り1953他","lat":36.727575,"lng":137.05074722,"geo_status":"db","era":"明治5年頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"石造及び木造2階建、瓦葺、建築面積49㎡、渡廊下付","structure_material":"石造及び木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0168","desc":"旧家の主屋東に位置する米蔵。二階建切妻造平入の南北棟で置屋根形式の桟瓦葺。西に戸口を設け、西・南面に良材を用いた鉄格子付の下屋を付す。一階は石造で土間一室、二階を木造井籠組一室で外壁漆喰仕上、西面を下見板で覆う。石と木による珍しい組積造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014595"},{"id":"00014597","register_sub_id":"101","register_pk":"515139","name":"吉田家住宅板塀","kana":"よしだけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市二口字馬渡り1953他","lat":36.72743333,"lng":137.05063056,"geo_status":"db","era":"明治5年／昭和前期改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、延長40m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0170","desc":"主屋西南を敷地に沿って矩折に囲う板塀。基礎は石積に布石を載せ、通りに面した西辺中央に賓客用の切抜門を開ける。南辺は座敷に面する庭園の範囲は虫食穴を有する舟板を転用して横板張とし、これ以外は縦板張とする。風格ある旧家の表構えを形成する板塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014597"},{"id":"00014594","register_sub_id":"101","register_pk":"515136","name":"吉田家住宅主屋","kana":"よしだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市二口字馬渡り1953他","lat":36.72755556,"lng":137.05056944,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造2階建、瓦葺、建築面積272㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0167","desc":"二口熊野新宮の参詣路に面する旧家の大規模な主屋。二階建切妻造妻入桟瓦葺で、長大な妻面に束と貫を重ねてアズマダチの特徴を示し、繊細な格子を構える。広間や茶の間は漆塗軸組で吹抜に豪壮な梁組を現す。旧家の風格を備え、地域の歴史的景観の核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014594"},{"id":"00014596","register_sub_id":"101","register_pk":"515138","name":"吉田家住宅土蔵","kana":"よしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県射水市二口字馬渡り1953他","lat":36.7275,"lng":137.05082222,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0169","desc":"主屋の南東に位置する道具蔵。基壇上に建つ二階建切妻造平入の南北棟で置屋根形式の桟瓦葺。西に出入口を設けて下屋を付し、内部は各階とも一室の板敷で西北に階段を設ける。外壁は漆喰仕上で腰をモルタル洗出仕上とし開口部に鉄扉を用いた近代らしい土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014596"},{"id":"00015432","register_sub_id":"101","register_pk":"533447","name":"吉村家住宅主屋","kana":"よしむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市金屋1420","lat":36.68912222,"lng":137.16494444,"geo_status":"db","era":"明治前期／大正3年頃移築、昭和44年・同57年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積259㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0174","desc":"神通川西岸の集落に位置する農家の主屋。敷地中央に東面して建つ切妻造妻入桟瓦葺で、内部は北を土間、東面中央に式台を設け、南列中央に座敷を配す。ヒロマやチャノマ上部を吹抜とし豪壮な梁組をみせる。通りに面したアズマダチの意匠が地域の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015432"},{"id":"00007207","register_sub_id":"101","register_pk":"108189","name":"赤倉家住宅主屋","kana":"あかくらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市魚町110","lat":37.048275,"lng":136.960327,"geo_status":"db","era":"明治後期／昭和54改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"17 － 0192","desc":"通りに北面して建つ平入町家。間口８．２ｍの木造２階建。前方を土間床のミセとし、その奥、西側にニワ、東を床上居室とする。２階は八畳２室を東西に並べ、正面側に半間幅の板間を通す。２階正面の格子や袖卯建など、伝統的な町家の表構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007207"},{"id":"00009263","register_sub_id":"101","register_pk":"194056","name":"あかつき屋","kana":"あかつきや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県金沢市暁町623","lat":36.56305505,"lng":136.67038372,"geo_status":"db","era":"昭和8年／平成22年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0240","desc":"北西角地に建つ木造二階建、切妻造桟瓦葺の町家。西面平入で、背面北寄りに片流屋根の水廻りを突出する。間口三間の正面下屋庇の北端一間を戸口、南側二間は出格子とする。二階は中央二間を出格子とする。北側面は下見板張である。建ちの高い近代町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009263"},{"id":"00003965","register_sub_id":"101","register_pk":"104955","name":"浅永家住宅主屋","kana":"あさながけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市浅野本町一丁目211","lat":36.580994,"lng":136.660873,"geo_status":"db","era":"江戸末期／明治中期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積264㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0095","desc":"金沢旧市域のすぐ外側に位置する農家。東面する，木造２階建，切妻造，妻入の身舎に下屋を回し，表側を広いニワ，奥を広大な床上部とする。差物や大梁による豪壮な架構の民家で，正面に漆喰壁と軸部，小屋材が鮮やかな対比をみせる姿は，周囲でも一際目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003965"},{"id":"00003966","register_sub_id":"101","register_pk":"104956","name":"浅永家住宅土蔵","kana":"あさながけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市浅野本町一丁目211","lat":36.58094886,"lng":136.66070983,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0096","desc":"主屋の南西に廊下で接続して建つ。桁行５間梁間３間，土蔵造，２階建，切妻造，桟瓦葺で，腰部を化粧目地を切って石積風にみせ，その上部を白漆喰塗仕上げとし，置屋根をのせる。戸口，窓回りに額縁型を塗りだした丁寧なつくりで，屋敷構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003966"},{"id":"00011935","register_sub_id":"101","register_pk":"211083","name":"飯田家住宅主屋","kana":"いいだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市小立野五丁目119","lat":36.554056,"lng":136.679156,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積234㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-269","desc":"金沢城の南東方、旧城下町の辺縁部の小立野台地に位置する住宅。外観はハーフティンバーでまとめ、平家に見えるが小屋裏に二階を設け収納空間とする。玄関、応接間は洋風意匠でまとめ、中廊下を通して左右に和室を配し、全体を大屋根でまとめる構成が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011935"},{"id":"00011936","register_sub_id":"101","register_pk":"211084","name":"飯田家住宅塀","kana":"いいだけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市小立野五丁目119他","lat":36.553946,"lng":136.678923,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"コンクリート造、総延長57m、門柱付","structure_material":"コンクリート造","registered":"2017.10.27(平成29.10.27)","register_no":"17-270","desc":"敷地南面から西面にかけて延びる塀。総延長五七メートルで、道路側と敷地側に高さ一・一メートルのコンクリートを立ち上げ、間に土を入れて生垣とする。西面中央には門柱を立てて入口とする。主屋と一連で建設されたと考えられ、街路景観に寄与する塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011936"},{"id":"00003955","register_sub_id":"101","register_pk":"104945","name":"泉家住宅主屋","kana":"いずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市昌永町14-20","lat":36.5801881,"lng":136.65701625,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、石綿セメント板葺、建築面積176㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0085","desc":"金沢城北方約１．５㎞にある。間口の広い一部２階建，切妻造，妻入の建物で，室内は床を備えた座敷，居間をはじめ多数の小間に仕切る。当初石置板葺の緩勾配の屋根，漆喰に小屋束，貫が鮮やかな対比をみせる正面の姿は幕末金沢の中下級武士住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003955"},{"id":"00003956","register_sub_id":"101","register_pk":"104946","name":"泉家住宅土蔵","kana":"いずみけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市昌永町14-20","lat":36.58025144,"lng":136.65694211,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0086","desc":"主屋の北下手，板の間に接して建つ。桁行３間梁間２間半規模，２階建，切妻造，桟瓦葺の土蔵造だが，軒裏，螻羽は塗り込めない。１階南面中央に戸口を開き，２階東面に大きめの窓をあける。小規模で簡素だが，戸口を掛け子塗りとするなど丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003956"},{"id":"00003417","register_sub_id":"101","register_pk":"104407","name":"伊東家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市花園八幡町ハ100甲","lat":36.63291207,"lng":136.71560528,"geo_status":"db","era":"明治10頃／昭和8増改造","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積310㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0079","desc":"金沢市北部郊外の山裾に建つアズマダチ風民家。間取は，土間ニワと４２畳規模のオエの奥に２列５室を並べ，東南にハナレを突き出す。ニワ・オエ境で３段の梁組と多数の貫を見せた妻を立ち上げ，ニワを下屋内に取り込んだ正面構えに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003417"},{"id":"00005830","register_sub_id":"101","register_pk":"106816","name":"上野家住宅主屋","kana":"うえのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市石引1-15-31","lat":36.55396376,"lng":136.67261969,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"17 － 0158","desc":"細長い敷地で，旧診療所の奥に建つ。桁行５間，梁間６間の規模で，木造２階建，切妻造，桟瓦葺とする。１階は通り庭が存在した伝統的な町家の平面形式とし，２階には床付きの座敷など４室を設ける。診療所と住居の動線を分ける点は，都市住宅の近代化を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005830"},{"id":"00005706","register_sub_id":"101","register_pk":"106694","name":"上野家住宅土蔵","kana":"うえのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市石引1-15-31","lat":36.55390979,"lng":136.67264586,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"17 － 0159","desc":"主屋側面に隣接して建つ内蔵で，桁行２間，梁間２間半，土蔵造２階建で，切妻造，桟瓦葺の置屋根形式とする。外壁を白漆喰塗とし，下屋状の主屋納戸の朱壁と鮮やかな対比を示し，主屋縁側からの敷地内の景観を整える存在として貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005706"},{"id":"00007025","register_sub_id":"101","register_pk":"108007","name":"江沼神社竹涇館","kana":"えぬまじんじゃちっけいかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺八間道55","lat":36.30853138,"lng":136.3087088,"geo_status":"db","era":"明治33年／昭和41年頃移築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"17 － 0190","desc":"境内の入口付近、参道に面して建つ。南北棟の寄棟造桟瓦葺の木造２階建を中心に、入母屋造の式台を付設する切妻造平屋建を西面北端に付ける。トコやトコ脇をもつ上段の間と大広間を続き座敷として設け、東面に畳廊下と広縁を通す。公的な接客空間を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007025"},{"id":"00007026","register_sub_id":"101","register_pk":"108008","name":"江沼神社梅花庵","kana":"えぬまじんじゃばいかあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市大聖寺八間道55","lat":36.30937907,"lng":136.30775659,"geo_status":"db","era":"江戸末期／明治前期・昭和41移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"17 － 0191","desc":"境内の北西に位置する。南面する木造平屋建で、切妻造妻入鉄板葺。外壁は漆喰の大壁仕上げで、竪板を高く張る。内部は玄関と口ノ間、主座敷を南北に一列に並べる。主座敷にはトコやトコ脇、付書院を構え、天井に大きく四季草花図を描くなど華やかなつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007026"},{"id":"00003410","register_sub_id":"101","register_pk":"104400","name":"大屋家住宅表門","kana":"おおやけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市長町1-1-37","lat":36.56366862,"lng":136.65071519,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0072","desc":"主屋の東方に位置し，屋敷地北側の道路が南と東に矩折となる東辺沿い道路からやや奥まって建つ。間口７尺規模の棟門で，土塀にむけて袖塀を従える。緩やかな起り付きの桟瓦葺，切妻屋根に特色があり，土塀とともに武家屋敷の街区景観を形成する一要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003410"},{"id":"00003411","register_sub_id":"101","register_pk":"104401","name":"大屋家住宅北塀","kana":"おおやけじゅうたくきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市長町1-1-37","lat":36.56375014,"lng":136.65054502,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、板葺及び瓦葺、延長43m","structure_material":"土塀","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0073","desc":"屋敷地北辺から表門へ向けて南に折れ曲がる土塀。亀甲積風の３～４段の石積基礎の上に土塀を築き，北辺沿いは板葺屋根を，東辺沿いは桟瓦葺屋根を戴く。表門とともに長町武家屋敷地区における歴史的小路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003411"},{"id":"00003409","register_sub_id":"101","register_pk":"104399","name":"大屋家住宅主屋","kana":"おおやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市長町1-1-37","lat":36.56364793,"lng":136.65051134,"geo_status":"db","era":"江戸末期／明治期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0071","desc":"武家屋敷地区を流れる大野庄用水沿いの屋敷地に東を正面として建つ。緩勾配の板葺石置き屋根の棟を明治期に高めてアズマダチ風に改造し，玄関も入母屋造に変えてはいるが，内部は創建時の間取りを良く残し，藩政時代の武家屋敷の様子を伝えていて貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003409"},{"id":"00003412","register_sub_id":"101","register_pk":"104402","name":"大屋家住宅南塀","kana":"おおやけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市長町1-1-37","lat":36.56348119,"lng":136.65045566,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長20m","structure_material":"土塀","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0074","desc":"大野庄用水沿い，屋敷地南辺に建つ。大野庄用水の護岸と一体となった亀甲積風石積基礎をもつ。ほぼ中央に潜口を設けるほか，西端部において用水を庭に引き込む取水口と排水口，洗場を設える。用水と武家屋敷の関係を物語る遺構のひとつとして貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003412"},{"id":"00011122","register_sub_id":"101","register_pk":"205229","name":"奥野家住宅主屋","kana":"おくのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県河北郡津幡町字川尻タ91","lat":36.673707,"lng":136.717955,"geo_status":"db","era":"明治19／大正12移築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積301㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"17 - 0254","desc":"河北潟にほど近い川尻地区に位置する。富山県西部から移築された、大型のいわゆるアズマダチ民家で、妻入とする。式台奥の広間はワクノウチと呼ばれる太い貫を多用した構法を採るなど、内外とも地域的な特色を見せる。座敷部も土縁を伴う続き間座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011122"},{"id":"00011123","register_sub_id":"101","register_pk":"205230","name":"奥野家住宅土蔵","kana":"おくのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県河北郡津幡町字川尻タ91","lat":36.673532,"lng":136.718039,"geo_status":"db","era":"明治中期／大正12移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積93㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"17 - 0255","desc":"米蔵と道具蔵の二棟からなる。はじめ米蔵が当地に設けられ、道具蔵が主屋とともに富山県西部から移築された際に、壁を共有して一体の横板張りの鞘で覆い、敷地内側に下屋を付けたとみられる。下屋側の腰には六角形の海鼠瓦を貼るなど、要所に装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011123"},{"id":"00011124","register_sub_id":"101","register_pk":"205231","name":"奥野家住宅門","kana":"おくのけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県河北郡津幡町字川尻タ91","lat":36.673552,"lng":136.717892,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"17 - 0256","desc":"通りに面して、主屋式台の前面に建つ一間薬医門。主屋移築と同時期に建設されたとみられ、大型の主屋に対応して、間口は二・七メートルと広くとる。屋根は桟瓦葺とする。堂々とした風格の門で、屋敷正面にあって、街路景観に欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011124"},{"id":"00005433","register_sub_id":"101","register_pk":"106421","name":"懐古館（旧飯田家住宅）主屋","kana":"かいこかん（きゅういいだけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県七尾市古屋敷町タ8-6-1","lat":37.02428079,"lng":136.97634655,"geo_status":"db","era":"江戸後期／明治末期・大正期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積281㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0153","desc":"敷地中央に建ち，桁行９間，梁間６間の規模で，木造平屋建，入母屋造，茅葺，平入とし正面の軒を瓦葺きとする。西側に土間をとり，東側にブツマ，ザシキ，ナカノマを並べ，ブツマに床の間を構え，その裏に隠し仏壇を置く。能登の民家形式の特徴をもつ農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005433"},{"id":"00004954","register_sub_id":"101","register_pk":"105944","name":"勝本家住宅主屋","kana":"かつもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町123","lat":37.04810948,"lng":136.96128809,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"17 － 0129","desc":"東西に通る一本杉通り北側に屋敷を構える。南面して建つ切妻造２階建，平入の町家で，西側を玄関土間とし，ミセノマを挟んで東に落棟のザシキを延ばし，正面は腕木で出桁を支え深い軒をつくる。明治３８年大火以前の七尾の伝統的な町家形式をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004954"},{"id":"00012895","register_sub_id":"101","register_pk":"367998","name":"金沢町家兼六","kana":"かなざわまちやけんろく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市昭和町224","lat":36.57432222,"lng":136.64611944,"geo_status":"db","era":"明治21年頃／昭和13年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺及び金属板葺、建築面積48㎡、背面物置付","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 284","desc":"金沢駅南側を横切る金石街道に北面して建つ。切妻造桟瓦葺の二階建で、背面に平屋建の物置を付す。正面は道路に斜行する敷地形状にあわせて突出部を設け、パラペットを立ち上げてモルタル大壁洗出しの洋風意匠で整える。昭和初期の趣向を伝える町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012895"},{"id":"00008272","register_sub_id":"101","register_pk":"133914","name":"観田家住宅主屋","kana":"かんだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市金石西2-345","lat":36.60252515,"lng":136.59156918,"geo_status":"db","era":"明治3年","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"17 － 0207","desc":"南北棟とする切妻造桟瓦葺の木造２階建を中心に、東北に座敷や茶室、西面に待合などを付設する。外壁は板張で、妻壁上部は漆喰仕上げで小屋組を見せる。座敷まわりは土縁をまわし、赤壁仕上げとし、華美な座敷飾りを構える。質の高い意匠をもつ近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008272"},{"id":"00008273","register_sub_id":"101","register_pk":"133915","name":"観田家住宅西蔵","kana":"かんだけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市金石西2-345","lat":36.60250964,"lng":136.59145381,"geo_status":"db","era":"明治3年","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"17 － 0208","desc":"主屋の西南、通り沿いに建つ。桁行７．３ｍ梁間５．５ｍの土蔵造２階建、南北棟の切妻造桟瓦葺。南面に蔵前を付ける。通り側の外壁は、腰の石貼より上部を全面竪板張とし、縦長の開口を穿ち、木製の出窓枠を付す。東面は腰を輪違の海鼠壁と独特の仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008273"},{"id":"00008274","register_sub_id":"101","register_pk":"133916","name":"観田家住宅西塀","kana":"かんだけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県金沢市金石西2-345","lat":36.60242131,"lng":136.59146639,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、鉄板葺、延長11m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"17 － 0209","desc":"西側道路に沿って西蔵南西角から南方向に建つ。木造、切妻造鉄板葺、延長１１ｍ。布石上に柱を建て、腕木を出し、軒桁を支持する。北端間に両開戸を吊り、他間は欄間を付し、舟板を横に張る。北前船で栄えた港町らしい佇まいを呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008274"},{"id":"00004955","register_sub_id":"101","register_pk":"105945","name":"神野家住宅主屋","kana":"かんのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県七尾市塗師町36-1","lat":37.04442934,"lng":136.96873886,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"17 － 0130","desc":"南側の街路に接して屋敷を構える。歯科医院として建てられた洋風の町家で，北を正面とした切妻造２階建，桟瓦葺，平入の形式。モルタル洗い出し仕上げの正面外壁は目地を付けて石造風に見せる。洋風の造形は１階窓枠上の装飾や軒廻りのデンティルにみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004955"},{"id":"00005993","register_sub_id":"101","register_pk":"106978","name":"菊知家住宅表門","kana":"きくちけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市北森本町ル15","lat":36.623634,"lng":136.69689874,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造、瓦葺、間口2.4m、袖塀付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"17 － 0162","desc":"主屋の西北に，旧街道からやや奥まって建つ，切妻造，桟瓦葺の棟門。間口８尺で乳金物，八双金物を飾った両開板扉を吊り込み，縦格子の欄間を設け，肘木形の女梁を用いる。左手表側に矩折れに張り出した袖塀に一体として屋根を架け，特色ある景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005993"},{"id":"00005991","register_sub_id":"101","register_pk":"106976","name":"菊知家住宅主屋","kana":"きくちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市北森本町ル15","lat":36.623444,"lng":136.696976,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積370㎡","structure_material":"木造平屋一部2階建","registered":"2006.11.29(平成18.11.29)","register_no":"17 － 0160","desc":"旧北国街道に西面して敷地を構える。切妻造，桟瓦葺の妻入で，妻壁に梁と貫を重ねるあずまづくりで，西端を土間，東を床上の居室とする。１０畳２間の座敷をもち，東に奥座敷を増築している。材を吟味し，施工も良質。伸びやかな屋根が特色ある景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005991"},{"id":"00005992","register_sub_id":"101","register_pk":"106977","name":"菊知家住宅土蔵","kana":"きくちけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市北森本町ル15","lat":36.623329,"lng":136.696884,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"17 － 0161","desc":"主屋の南に建つ南北棟の土蔵造２階建で，切妻造，桟瓦葺の置屋根を架ける。桁行３間，梁間２間半で，西面に戸口を設け，蔵前が主屋水屋に接続する。切石積の高い基礎上に建ち，外壁は押縁下見板張で，東面中央に上下２つの窓を開く。たちが高く存在感ある外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005992"},{"id":"00002141","register_sub_id":"101","register_pk":"103131","name":"北大路魯山人寓居主屋","kana":"きたおおじろさんじんぐうきょしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市山代温泉18-5","lat":36.28750362,"lng":136.36067121,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積72㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"17 － 0041","desc":"加賀山代温泉の中心街，服部神社下に位置する。北大路魯山人が大正期に山代温泉滞在中に仕事場とした建物として知られる。木造２階建，切妻造で，当地方に見られる妻構成をとるが，北東部を入隅として奥まったところに玄関を設け，煙出の小屋根を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002141"},{"id":"00002142","register_sub_id":"101","register_pk":"103132","name":"北大路魯山人寓居土蔵","kana":"きたおおじろさんじんぐうきょどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市山代温泉18-5","lat":36.28751717,"lng":136.36056428,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、亜鉛鉄板葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"17 － 0042","desc":"屋敷地の西端に位置し，主屋とは棟を直交する形で建つ。南北棟，切妻造，桟瓦葺の２階建土蔵で，桁行４間，梁行２間規模，北面と東面に戸前を設け，南面に小さな窓を開ける。主屋とともに，魯山人ゆかりの建造物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002142"},{"id":"00001057","register_sub_id":"101","register_pk":"102047","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）主屋","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34900566,"lng":136.30960089,"geo_status":"db","era":"明治3頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造２階建，瓦葺，建築面積369㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0022","desc":"北前船の船主であった酒屋宗七郎の居宅として建築されたと伝える大規模な主屋である。敷地の中央にあり，木々の間にゆったりとした妻を見せて建つ。背後に離れ座敷及び隠居部屋が付属するが，主体部は伝統的な平面形態を踏襲する質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001057"},{"id":"00001058","register_sub_id":"101","register_pk":"102048","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵１","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞういち","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.3490801,"lng":136.30962195,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造２階建，前室附属，瓦葺，建築面積30㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0023","desc":"主屋の背後に位置し，離れ座敷及び隠居部屋とも中庭を囲むように建つ小規模な土蔵。北妻側に出入口があり，庇屋根を架けて蔵前を造っている。主屋等とは廊下で繋がっているが，上部を白漆喰，下部をなまこ壁で仕上げる外観はひときわ目立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001058"},{"id":"00001063","register_sub_id":"101","register_pk":"102053","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵５","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞうご","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34886356,"lng":136.3100084,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造２階建，瓦葺，建築面積38㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0028","desc":"前面道路に沿って建つ妻入の２階建土蔵で，切石積みの基礎上に建ち，１階は味噌の保管に用い，２階に文書類を納めた。妻側にのみ窓を設ける極めて閉鎖的な外観になるが，他の土蔵同様に軒廻りを除き竪板貼りとし，周辺の建物との調和を保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001063"},{"id":"00001061","register_sub_id":"101","register_pk":"102051","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵３","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞうさん","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34909964,"lng":136.31010539,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造２階建，瓦葺，建築面積26㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0026","desc":"主屋の建つ敷地の向かい側にある一連の土蔵群の北端にあり，道路に接する切石積みの基礎の上に建つ小規模の土蔵。南妻側に庇屋根を架け蔵前として出入口を設ける。家財道具を収納する蔵で，外観は軒廻りを除き竪板貼りとする標準的なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001061"},{"id":"00001065","register_sub_id":"101","register_pk":"102055","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵７・８","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞうなな・はち","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34872371,"lng":136.30999412,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，物置部分附属，瓦葺，建築面積54㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0030","desc":"軒を接して並列して建つ平入の２棟の土蔵に覆屋をかけた形の建物で，米蔵として利用されていた。覆屋の外観は，軒廻りを漆喰で塗り込め外壁を竪板貼りとするなど周辺の土蔵にあわせて一連の景観を形成する形になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001065"},{"id":"00001059","register_sub_id":"101","register_pk":"102049","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵２","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞうに","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34887409,"lng":136.30988359,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造２階建，瓦葺，建築面積20㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0024","desc":"主屋の東南に建つ２階建の美術品や道具を納めた土蔵。主屋とつながる蔵前（北・西面）には現在改造がみられるが，本体の主要部分の保存状況は良好である。道路沿いに妻を見せ，軒廻りは漆喰仕上げとするほかは竪板貼りとし屋敷構えの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001059"},{"id":"00001062","register_sub_id":"101","register_pk":"102052","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵４","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞうよん","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34909589,"lng":136.31015802,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積25㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0027","desc":"土蔵３と並行してその東側に建つ平屋建の小規模な平屋建の建物。漁労具や葬式用具等を納めた蔵で，基礎廻りの石積みが低く，外壁を総竪板貼りとして軒廻りの垂木をそのままみせるなど，全体として極めて簡素な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001062"},{"id":"00001064","register_sub_id":"101","register_pk":"102054","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）土蔵６","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）どぞうろく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34879138,"lng":136.30999713,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造２階建，瓦葺，建築面積36㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0029","desc":"前面道路側に出入口を設けた２階建，妻入の土蔵。家財道具類を納めた蔵で，土蔵５と土蔵７・８の間に建つ。外観は素朴だが，蔵前部分は正面に引違戸を置き，左右の外壁は漆喰仕上げとするが，腰下は押縁板貼りとして変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001064"},{"id":"00001060","register_sub_id":"101","register_pk":"102050","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）物置１・下男小屋","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）ものおきいち・げなんごや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.3490628,"lng":136.31000164,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積37㎡，袖塀3.9m附属","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0025","desc":"主屋の建つ敷地の東面北側にあり，道路に接して建つ簡素な造りになる建屋。平面は，南半が土間及び居室からなる下男小屋で，西側は土庇となる。北半は内部を土間とする物置（もと炭小屋）であった。かつての生活の有様の一端を知る上で貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001060"},{"id":"00001066","register_sub_id":"101","register_pk":"102056","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）門１","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）もんいち","category":"住宅","subcategory":"その他工作物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34902671,"lng":136.30998585,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造，瓦葺，幅1.8m，塀延長3.6m附属","structure_material":"木造","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0031","desc":"主屋玄関口の北脇に建つ塀を兼ねる屋根付きの簡素な門で，１間幅の出入り口部分は板戸引き違いとする。両脇は真壁造りになり，上部が黒漆喰塗りで腰下は竪板貼りとする。主屋の建つ敷地の内向き部分を画する門で，生活の有様を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001066"},{"id":"00001067","register_sub_id":"101","register_pk":"102057","name":"北前船主屋敷蔵六園（旧酒谷長一郎家住宅）門２","kana":"きたまえせんしゅやしきぞうろくえん（きゅうさかやちょういちろうけじゅうたく）もんに","category":"住宅","subcategory":"その他工作物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市橋立町ラ47","lat":36.34898085,"lng":136.30998585,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造，瓦葺，塀延長6.9m附属","structure_material":"木造","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0032","desc":"主屋正面に設けられた一対の太い角柱の親柱だけからなる門で，頭部に銅製の蓋が付く。門の両脇には透かし付きの低い塀及び腰高塀が取り付き，屋敷地の外観を飾っている。簡素ながら落ち着いた構えは，北前船の船主の居宅にふさわしい独特の威厳が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001067"},{"id":"00003963","register_sub_id":"101","register_pk":"104953","name":"北村家住宅主屋","kana":"きたむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市菊川2-8-10","lat":36.551823,"lng":136.661285,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺一部瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0093","desc":"旧足軽組地にある住宅。切妻造，妻入の木造２階建で，１階は表通りに北面して玄関を開き，奥に座敷，居間，茶の間などの居室を配し，２階にも部屋を取る。漆喰に小屋束・貫の対比も鮮やかな棟高の低い緩勾配の切妻を見せた姿は，地区の歴史景観に欠かせない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003963"},{"id":"00003958","register_sub_id":"101","register_pk":"104948","name":"木村家住宅主屋","kana":"きむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市彦三町2-11-11","lat":36.57588882,"lng":136.65827306,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積152㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0088","desc":"大通りに北面して建つ和風住宅。入母屋造，桟瓦葺の木造２階建とし，１階正面中央に玄関を突出する。玄関脇応接室以外は和室で，座敷飾り等に銘木を使い，壁は弁柄，群青色の砂壁とする。正面に入母屋の妻を重ねたたちの高い外観は，地区でも一際目立つ存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003958"},{"id":"00014796","register_sub_id":"101","register_pk":"519054","name":"旧石川家住宅主屋","kana":"きゅういしかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市小立野二丁目459","lat":36.55266111,"lng":136.68024444,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積134㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0317","desc":"金沢城跡南東に位置する退役陸軍大佐の住宅。敷地東奥に西面し、赤瓦葺の半切妻屋根に外壁下見板張とし正面は幾何学的意匠の妻飾と出窓で飾る。一階応接間は洋室とする他は和室とし二階に客用座敷を設ける。上質な和洋折衷住宅で周囲の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014796"},{"id":"00014797","register_sub_id":"101","register_pk":"519055","name":"旧石川家住宅門及び土塁","kana":"きゅういしかわけじゅうたくもんおよびどるい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市小立野二丁目459他","lat":36.55255,"lng":136.68003056,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門 コンクリート造、間口2.7m、南脇門付 土塁土留 コンクリート造、総延長24m","structure_material":"門 コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0318","desc":"敷地の西面に建つ門及び土塁。門は前面道路から斜めに引込み、コンクリート造角柱を三本立て、北は正門で両開戸、南は脇門で片開戸を吊る。土塁はコンクリートで側面の土留と前面の低い土留をつくり、山形に土を盛る。昭和初期開発の住宅地の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014797"},{"id":"00003968","register_sub_id":"101","register_pk":"104958","name":"旧市谷家住宅主屋","kana":"きゅういちたにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市北袋町ヱ36","lat":36.49378454,"lng":136.74909438,"geo_status":"db","era":"大正13／昭和45移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0098","desc":"炭焼きを生業とした家の住居。木造，２階建，切妻造，妻入の身舎の正面に下屋を付け，表側を土間，奥にオエ，ザシキなどの部屋をとる。漆喰壁に軸部の対比が鮮やかな外観のアズマダチの民家で，内部は良質な欅の大径材による柱，差物，梁で豪壮な架構を組む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003968"},{"id":"00011290","register_sub_id":"101","register_pk":"209126","name":"旧稲邑家住宅主屋","kana":"きゅういなむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県鹿島郡中能登町小田中ム103","lat":36.94266073,"lng":136.87976683,"geo_status":"db","era":"明治42／平成23改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積244㎡、南方門付","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0267","desc":"旧能登街道沿いに建つ。妻入のいわゆるアズマダチ民家。右土間で、床上部はチャノマを介して続き間座敷に至る平面を持つ。チャノマには当地でサシモノと呼ぶ井桁状に太い梁を架ける伝統的要素を備え、座敷の脇には広い土縁を持つなど地域的な特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011290"},{"id":"00003969","register_sub_id":"101","register_pk":"104959","name":"旧北尾家門","kana":"きゅうきたおけもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市北袋町ヱ36","lat":36.49460456,"lng":136.74935342,"geo_status":"db","era":"明治中期／昭和46移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0099","desc":"もと豪農の屋敷の表門として建設された。桁行７間，梁間２間，入母屋造，桟瓦葺の長屋門で，中央部に方２間，切妻屋根の望楼をのせ，門口上部の前後に唐破風を付す。民家の長屋門でありながら，社寺の楼門風の構えを取り入れた類例を見ない珍しい形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003969"},{"id":"00012900","register_sub_id":"101","register_pk":"368003","name":"旧下里家住宅主屋","kana":"きゅうくだりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県小松市大杉町寅110","lat":36.26841944,"lng":136.48598056,"geo_status":"db","era":"江戸末期／明治36年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 289","desc":"市南部の山村集落のもと農家主屋。南正面の切妻造桟瓦葺妻入の二階建、南から土間とヒロマを並べ、奧に田字形に室を配する。ヒロマは吹抜けに木太い梁組をみせ、西北隅のジョウザは仏壇前に幅半間の上段を備える。加賀地方上層農家の形式を伝える民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012900"},{"id":"00007021","register_sub_id":"101","register_pk":"108003","name":"旧小倉家住宅離れ","kana":"きゅうこくらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市芳斉1-2-4他","lat":36.5692201,"lng":136.6496308,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"17 － 0186","desc":"東面する敷地の南辺近く中央に建つ木造２階建。東西棟の入母屋造で、東妻面には一段落として入母屋造破風を付け、特徴的な外観とする。外壁は下見板張で、小壁を弁柄色に仕上げる。内部も赤壁で、トコや書院、欄間ほか、数寄屋風の洗練された意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007021"},{"id":"00007023","register_sub_id":"101","register_pk":"108005","name":"旧小倉家住宅離れ表門","kana":"きゅうこくらけじゅうたくはなれおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市芳斉1-2-4他","lat":36.569168,"lng":136.650024,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、銅板葺、間口1.6m、両袖塀付","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"17 － 0188","desc":"旧武家町の通りに東面して建つ。１間腕木門で、両脇に袖塀を付ける。屋根は切妻造銅板葺とし、棟瓦を置く。棟木や母屋に磨き丸太を用い、柱を名栗仕上げとし、楣上部に繊細な格子欄間を置く。丁寧なつくりになる数寄屋風の門の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007023"},{"id":"00013989","register_sub_id":"101","register_pk":"508249","name":"旧米谷家住宅主屋","kana":"きゅうこめたにけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県小松市花坂町蛇谷6-1","lat":36.38470556,"lng":136.48645278,"geo_status":"db","era":"江戸後期／昭和62年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"17 - 0303","desc":"海岸沿いの集落から移築した廻船問屋の主屋。木造平屋建、寄棟造茅葺平入、土間側を除く三方にこけら葺の下屋を付す。土間は石敷、床上は広間型で上手表に仏間、奥に納戸、表側に押入を配す閉鎖的な構え。典型的な加賀地方広間型民家の間取を示して貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013989"},{"id":"00011945","register_sub_id":"101","register_pk":"354921","name":"旧丹後家住宅表塀","kana":"きゅうたんごけじゅうたくおもてへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県鹿島郡中能登町能登部上へ12-1","lat":36.967534,"lng":136.873485,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、総延長21m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"17-279","desc":"玄関前を挟んで左右に延びる板塀で前庭を取囲むように敷地を画する。高さ二・四メートル、延石を伏せて柱を立て、腕木を出して疎垂木を配り、桟瓦を葺く。塀上部は透かしのある漆喰塗で、腰を羽目板張とする。街道の景観を構成する重要な要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011945"},{"id":"00011943","register_sub_id":"101","register_pk":"354919","name":"旧丹後家住宅主屋","kana":"きゅうたんごけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県鹿島郡中能登町能登部上へ12-1他","lat":36.967443,"lng":136.873624,"geo_status":"db","era":"昭和8年／昭和前期改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積308㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-277","desc":"街道からやや奥まって建つアズマダチの主屋。木造平屋一部二階建、間口六間半、奥行七間半規模で四周に下屋が廻る。大戸を潜るとニワに入る引戸と一間幅のトオリドマの引戸が並ぶ。麻織物で繁栄した能登部上地域の典型を示す近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011943"},{"id":"00011944","register_sub_id":"101","register_pk":"354920","name":"旧丹後家住宅土蔵","kana":"きゅうたんごけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県鹿島郡中能登町能登部上へ12-1他","lat":36.967262,"lng":136.873627,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積71㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-278","desc":"敷地南端角に建つ。ニ棟の土蔵がひとつの覆屋に収まる土蔵造二階建、大壁造、瓦葺の置屋根とし、外壁は上部を白色モルタル仕上げとし、東面の腰は下見板張で、その他を人造石仕上とする。北側に庇を付す。笠木状の簡明な意匠の窓枠が全体を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011944"},{"id":"00011946","register_sub_id":"101","register_pk":"354922","name":"旧丹後家住宅庭門及び塀","kana":"きゅうたんごけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県鹿島郡中能登町能登部上へ12-1","lat":36.967452,"lng":136.873351,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"庭門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長29m","structure_material":"庭門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"17-280","desc":"主屋東側の庭園を画する板塀。北面と西面は道路に面し、前庭を画する表塀と接する部分で矩折れ、棟を切り上げて、一間幅の門を開く。切石を二段に重ねて柱を立て、腕木を出して疎垂木を配り、桟瓦を葺く。羽目板張とし、屋根との間に透かしを入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011946"},{"id":"00001042","register_sub_id":"101","register_pk":"102032","name":"旧月田家住宅","kana":"きゅうつきたけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市大聖寺神明町10","lat":36.30272891,"lng":136.30779426,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，鋼板葺，建築面積80㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0007","desc":"旧大聖寺藩下級武士の家で，旧藩邸（現錦城小学校）の南方，加賀神明宮などの社寺が集中する地区に建つ。木造平屋の簡素な武家住宅であるが，城下町における武家屋敷の佇まいを伝える数少ない遺構のひとつであり，城下町の空間構成を知るうえでも貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001042"},{"id":"00003225","register_sub_id":"101","register_pk":"104215","name":"旧中木家住宅石蔵","kana":"きゅうなかきけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市大聖寺魚町36","lat":36.30520049,"lng":136.31068949,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積20㎡","structure_material":"木骨石造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0065","desc":"主屋の南方，土蔵の東方に東西棟で建つ。桁行３間梁間２間，切妻造，越前瓦葺の平入２階建石蔵で，構造は木軸部の外側に凝灰岩を積んだ木骨石造とする。北面に１間幅の下屋を差掛けて蔵前とし，やや西寄りに金庫風の両開戸を付けて入口とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003225"},{"id":"00003223","register_sub_id":"101","register_pk":"104213","name":"旧中木家住宅主屋","kana":"きゅうなかきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市大聖寺魚町36","lat":36.30534115,"lng":136.310791,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0063","desc":"道路に北面して建つ間口４間の木造２階建平入町家で，西方下手チャノマ上部に天窓付きの吹抜けをもつ。屋根は越前瓦葺，表構えはセガイ造りとし，２階の袖卯建や１階板葺庇のサガリなどに特徴がある。城下町大聖寺における近代町家の好事例で，内部も上質。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003223"},{"id":"00003224","register_sub_id":"101","register_pk":"104214","name":"旧中木家住宅土蔵","kana":"きゅうなかきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺魚町35","lat":36.30524032,"lng":136.31059348,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0064","desc":"主屋の南西方に南北棟で建つ。桁行５間梁間３間半，切妻造，越前瓦葺の比較的規模の大きな２階建土蔵で，東面中央に入口を設け，主屋南西端に繋がる台所の延長部に蔵前をとる。基礎は石積とし，外壁は縦板張とする。棟押さえの凝灰岩の雁振りも特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003224"},{"id":"00003971","register_sub_id":"101","register_pk":"104961","name":"旧中屋家行在所表門","kana":"きゅうなかやけあんざいしょおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市北袋町ヱ36","lat":36.49448771,"lng":136.7498317,"geo_status":"db","era":"明治11／平成元移築","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0101","desc":"行在所への専用通用門で，表通りに面して建っていた。切妻造，銅板瓦棒葺の棟門で，親柱背後には控え柱を備える。両袖を付属し，向かって左の袖に潜りを開ける。小規模で簡素だが，持送りや腕木の端を繰形で飾り，屋根に強い起りを付け特徴ある姿にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003971"},{"id":"00003970","register_sub_id":"101","register_pk":"104960","name":"旧中屋家行在所主屋","kana":"きゅうなかやけあんざいしょしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市北袋町ヱ36","lat":36.4944313,"lng":136.74997267,"geo_status":"db","era":"明治11／平成元移築","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0100","desc":"明治天皇北陸巡幸の際の行在所で，もと金沢市内の大店薬種商の屋敷内に建設された。入母屋造，桟瓦葺の平屋で，床棚付１５畳の主室，８畳の次の間を中心に湯殿，便所等が付属する。簡素で軽快なつくりだが，長押を回して格式を保ち，透し彫り欄間を入れ飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003970"},{"id":"00009935","register_sub_id":"101","register_pk":"196082","name":"旧野村家住宅主屋","kana":"きゅうのむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市香林坊2-141","lat":36.56577062,"lng":136.65299614,"geo_status":"db","era":"大正11／昭和3頃改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積149㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"17 － 0245","desc":"敷地中ほどに東面する。一階は玄関奥に四畳の次の間、奥に八畳座敷を並べる。二階は彫刻欄間や青色の土壁で華やかに飾り、瀟洒な意匠とする。一階平面に当地の武家住宅の名残を伝え、二階妻壁は梁組を化粧で現すアズマダチの構成とする、地方的特色を示す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009935"},{"id":"00009936","register_sub_id":"101","register_pk":"196083","name":"旧野村家住宅土塀","kana":"きゅうのむらけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市香林坊2-141","lat":36.56584792,"lng":136.65301954,"geo_status":"db","era":"明治後期／大正11頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺及び金属板葺、総延長35m","structure_material":"土塀","registered":"2014.04.25(平成26.04.25)","register_no":"17 － 0246","desc":"敷地東面の門北側から矩折に北面にのびる土塀。玉石を丁寧に積上げて基礎とし、壁体は版築造の躯体に中塗仕上げとする。腕木を出して軒を受け、屋根は、東面は桟瓦葺、北面は金属板葺とする。武家地であった当地の伝統的な構えを伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009936"},{"id":"00013715","register_sub_id":"101","register_pk":"505247","name":"旧藤村家住宅（田村家住宅）板塀","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）いたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県野々市市本町二丁目133他","lat":36.53159167,"lng":136.61994167,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、銅板葺、総延長51m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 299","desc":"北面の裏門の東西及び離れと西面土塀間の敷地内の塀二棟からなり総延長五一メートル。北辺はコンクリート基礎上に柱を立て竪板張で、上部は格子欄間を嵌め笠木を銅板葺として裏門と意匠を揃える。敷地内は礎石に角柱を立て杉皮を張る。敷地内外の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013715"},{"id":"00013711","register_sub_id":"101","register_pk":"505239","name":"旧藤村家住宅（田村家住宅）後ろの蔵","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）うしろのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県野々市市本町二丁目133","lat":36.53153889,"lng":136.62017778,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 295","desc":"離れの南東に接続する。土蔵造二階建切妻造桟瓦葺。南北棟で西面する。南・西面は腰を下から戸室石亀甲張、笏谷石布張、海鼠壁として上部を漆喰塗とする等装飾的なつくりとするが、東面は中塗で留めるなど、南庭からの見栄えを強く意識した意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013711"},{"id":"00013713","register_sub_id":"101","register_pk":"505243","name":"旧藤村家住宅（田村家住宅）裏門","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）うらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県野々市市本町二丁目140-1","lat":36.53182222,"lng":136.62027778,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、銅板葺、間口2.0m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 297","desc":"敷地北側の通りに面して建つ。棟門形式で鉄棒の控がつく。角柱の本柱に楣を架け、女梁、男梁を渡して軒桁を受ける。屋根はむくりのある切妻造で銅板葺。柱間は板戸両開きで内法貫上は格子欄間である。垂木と梁の木口には金物を打つ。北辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013713"},{"id":"00013712","register_sub_id":"101","register_pk":"505241","name":"旧藤村家住宅（田村家住宅）表門","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県野々市市本町二丁目133","lat":36.53151389,"lng":136.61988333,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 296","desc":"街道に西面して建つ。棟門形式で、笏谷石の礎石に角柱の本柱を立て、冠木を渡し、梁を三本架けて軒桁を受ける。角柱の控柱は本柱と貫二段で繋ぐ。屋根は切妻造桟瓦葺。柱間は板戸二枚を内開きに建てる。左右の塀とともに旧北国街道の宿場町の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013712"},{"id":"00013708","register_sub_id":"101","register_pk":"505233","name":"旧藤村家住宅（田村家住宅）主屋","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県野々市市本町二丁目133","lat":36.53167778,"lng":136.62025833,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積247㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 292","desc":"旧北国街道の宿場町、野々市に所在。二階の一部を前方に張出して入母屋の妻を重ね、更に入母屋の玄関を付す等豪壮な外観。玄関から中廊下を通し南に座敷三室を並べ、北は内向きの室。二階は茶室等五室。材料を吟味し、欄間等の細部意匠に凝った近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013708"},{"id":"00013714","register_sub_id":"101","register_pk":"505245","name":"旧藤村家住宅（田村家住宅）土塀","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）どべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県野々市市本町二丁目133","lat":36.53146944,"lng":136.62004722,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土塀、瓦葺、総延長34m","structure_material":"土塀","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 298","desc":"旧北国街道に西面して建つ表門の左右に取付き、敷地南面の隣地境まで矩折れに続く。総延長は三四メートル。石積の基礎の上部に土塀を築き、天端は腕木を出して桟瓦葺の屋根を載せる。基礎の道路側は戸室石を切石積して化粧とする。敷地西・南辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013714"},{"id":"00013709","register_sub_id":"101","register_pk":"505235","name":"旧藤村家住宅（田村家住宅）離れ","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県野々市市本町二丁目133","lat":36.53161944,"lng":136.62006944,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 293","desc":"主屋南西に建つ。平屋建切妻造桟瓦葺で北に下屋、南に土縁を設ける。北西を玄関とし、北を幅広の板廊下、南を一二畳半の座敷及び続き間とする。明治天皇の御小休所となった旧主屋の一部と伝え、座敷境の彫刻欄間は富士を題材とするなど上質な設えを持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013709"},{"id":"00013710","register_sub_id":"101","register_pk":"505237","name":"旧藤村家住宅（田村家住宅）前の蔵","kana":"きゅうふじむらけじゅうたく（たむらけじゅうたく）まえのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県野々市市本町二丁目133","lat":36.53179167,"lng":136.62005,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積92㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"17 － 294","desc":"敷地北西隅、旧北国街道に西面して建つ。東西棟で二階建切妻造桟瓦葺。桁行梁間とも四間規模で西に大きな蔵前を設ける。柱の外面に板を張って土塗とする等、板蔵を土蔵に改修したとみられる。一、二階とも一室で中央に柱を立て棟を受ける。街道景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013710"},{"id":"00003421","register_sub_id":"101","register_pk":"104411","name":"旧本多家住宅長屋門","kana":"きゅうほんだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市本多町3-53-2","lat":36.55857345,"lng":136.65988272,"geo_status":"db","era":"江戸末期／明治初期・昭和40移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0083","desc":"本多家上屋敷に隣接した本多内記家の長屋門の主要部を移築したものと伝える。現状は桁行６間半，梁間２間規模で，石積基礎の上に建ち，屋根は寄棟造，桟瓦葺とし，正面左寄りに間口８尺の門を開く。金沢藩重臣クラスの武家屋敷地の面影を残す遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003421"},{"id":"00003967","register_sub_id":"101","register_pk":"104957","name":"旧宮下家住宅主屋","kana":"きゅうみやしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市北袋町ヱ36","lat":36.49505762,"lng":136.74859528,"geo_status":"db","era":"大正9／昭和45移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積195㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0097","desc":"炭焼きを生業とした家の住居。木造，２階建，切妻造，妻入の身舎の正面に下屋を付け，内部は表側にウマヤのある土間をとり，その奥を床上部とする。壁面の太い柱，妻面の小屋束と密に通した貫をみせるいわゆるアズマダチの民家で，外観はよく旧形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003967"},{"id":"00003957","register_sub_id":"101","register_pk":"104947","name":"小泉家住宅主屋","kana":"こいずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市本多町1-17-10","lat":36.553722,"lng":136.664963,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積206㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0087","desc":"木造２階建の中廊下型住宅。北面の西端部を突出した鈎形平面の主体部を中心に，北，南面に平屋を付属し，北面中央に入母屋屋根の玄関を突出する。和風を基調としつつ，応接室，書斎のある西端を洋風につくるたちの高い特異な外観は，住宅地の中で一際目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003957"},{"id":"00004534","register_sub_id":"101","register_pk":"105524","name":"五徳庵主屋","kana":"ごとくあんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺錦町52-1","lat":36.30560217,"lng":136.30466169,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"17 － 0124","desc":"門及び倉庫の北側に南面して建つ。木造，桟瓦葺の平屋建で，屋根は切妻造を基本とする。玄関と３畳の取次ぎが並ぶ東側に，８畳２室が南北に続き，西側には水回りと居室２室を置く。中級武家屋敷の流れを汲む明治期の住宅遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004534"},{"id":"00004535","register_sub_id":"101","register_pk":"105525","name":"五徳庵倉庫","kana":"ごとくあんそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県加賀市大聖寺錦町52-1","lat":36.30550404,"lng":136.30465152,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"17 － 0125","desc":"主屋の南方に位置し，敷地南面接道部分の東端に東西棟で建つ。木造２階建，切妻造，桟瓦葺で，北面に入口を設け，西面１階及び２階に窓が付く。外壁は下見板張で，北側から東側にかけて下屋が回り，主屋と繋がる。門とともに屋敷構えを構成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004535"},{"id":"00004536","register_sub_id":"101","register_pk":"105526","name":"五徳庵離れ","kana":"ごとくあんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市大聖寺錦町52-1","lat":36.30562535,"lng":136.30481707,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺及び瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"17 － 0126","desc":"北端が東に矩折れる敷地の東部に奥まって建つ。切妻造，鉄板葺の木造平屋建で，東・南・西の３面に桟瓦葺の下屋が廻る。６畳一間の小規模な離れ座敷で，床，棚，天井等の意匠に工夫が見られ，広い開口部を北側の庭に面して取る。大正期数寄屋離れの一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004536"},{"id":"00004537","register_sub_id":"101","register_pk":"105527","name":"五徳庵門","kana":"ごとくあんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県加賀市大聖寺錦町52-1","lat":36.30550076,"lng":136.30458642,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口4.1m","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"17 － 0127","desc":"敷地南端，倉庫の西側に，道路より後退して建つ。正面２間の木造腕木門で，西側１間が下見板張，東側１間が引込の板戸となり，切妻造，鉄板葺の屋根が架かる。柱や冠木は古く，旧藩時代の中級武家屋敷の門形式を示し，大聖寺藩時代の武家地の面影を今に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004537"},{"id":"00001376","register_sub_id":"101","register_pk":"102366","name":"時習庵主屋（旧堀家住宅）","kana":"じしゅうあんしゅおく（きゅうほりけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺神明町20","lat":36.3043448,"lng":136.30676293,"geo_status":"db","era":"明治期／昭和16一部改築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"17 － 0037","desc":"山裾に位置する旧武家屋敷地に営まれた近代和風住宅。道路に面する切妻造，２階建ての玄関棟の後方に入母屋造，平屋の座敷棟が接続する。座敷二室と広縁からなる座敷棟，昭和１６年建て替えの玄関棟ともに，木柄が細く，生漆塗りの上質な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001376"},{"id":"00002920","register_sub_id":"101","register_pk":"103910","name":"島村家住宅主屋","kana":"しまむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市神谷内町卜4","lat":36.59784271,"lng":136.68413071,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積269㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0062","desc":"江戸時代には肝煎を務めた旧家。主屋は切妻造・桟瓦葺，妻入で，正面に庇を設ける。正面妻は梁を４段に重ね，梁間を貫・束で整然と繋ぐ。梁組を見せる土間や客間，銘木を用いた丁寧なつくりの数寄屋風の座敷や控え間など，内外とも洗練された造形の近代民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002920"},{"id":"00007626","register_sub_id":"101","register_pk":"108608","name":"清水家住宅表門及び塀","kana":"しみずけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市中央通町376","lat":36.56338074,"lng":136.6479679,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"門 木造、瓦葺、間口2.0m、左右袖塀付、塀 木造、瓦葺、総延長18m、勝手口付","structure_material":"門 木造","registered":"2009.04.28(平成21.04.28)","register_no":"17 － 0206","desc":"表門は敷地北辺の中央に建つ一間腕木門。両脇に板張、上部黒漆喰の袖塀を設け、引分け戸をたてる。袖塀から続く塀は東西に総延長１８ｍ。切石積基礎の上に柱を建て腕木で軒を支持。下見板張の上部を黒漆喰壁とし、屋根桟瓦葺。落ち着きのある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007626"},{"id":"00007625","register_sub_id":"101","register_pk":"108607","name":"清水家住宅主屋","kana":"しみずけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市中央通町376","lat":36.56332599,"lng":136.64804791,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"17 － 0205","desc":"金沢城下に位置する。北面する妻入の木造２階建で、梁間１１ｍに切妻造屋根を架け、西に平屋を付設。正面妻は梁や束、貫を縦横に組み、下部を下見板張とし、右手に出格子を付ける。中央に玄関、その東に土縁を設ける。伝統的な民家の佇まいを残す近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007625"},{"id":"00011938","register_sub_id":"101","register_pk":"211086","name":"信行寺書院（和倉御便殿供奉殿）","kana":"しんぎょうじしょいん（わくらごべんでんぐぶでん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市和倉町ソ16他","lat":37.086938,"lng":136.914017,"geo_status":"db","era":"明治42年／昭和35年・同48年移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"17-272","desc":"明治四二年の皇太子行啓に際し建てられた御便殿のうち、供奉殿部分を移築したもので、本殿部分とは廊下を介して接続していた。現在はその廊下の南側に西から一二畳半座敷、一五畳、八畳を並べ南側にも部分的に縁を配す。便殿建築の希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011938"},{"id":"00009160","register_sub_id":"101","register_pk":"164713","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市中町8他","lat":36.40748416,"lng":136.44955818,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":"17 - 0234","desc":"中町通り沿いの東南角地に建ち、木造2階建、建築面積165平方メートル、入母屋造桟瓦葺。角を隅入りとし、入母屋の妻や軒庇を段違いに設けて変化のある外観とする。外部は開口部に格子を建て、内部では座敷に面皮材を用いるなど、上品なつくりの町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009160"},{"id":"00009162","register_sub_id":"101","register_pk":"164715","name":"鈴木家住宅土蔵","kana":"すずきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県小松市中町8他","lat":36.40751985,"lng":136.44940114,"geo_status":"db","era":"明治15年／昭和5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":"17 - 0236","desc":"敷地北西隅に建ち、桁行9.1メートル梁間4.6メートル、土蔵造2階建、切妻造桟瓦葺で、南面を出入口として蔵前を設ける。布石積の基礎に建ち、外壁漆喰塗仕上げで、両妻に窓を穿つ。昭和5年の小松大火に耐えた土蔵で、明治期の商家の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009162"},{"id":"00009161","register_sub_id":"101","register_pk":"164714","name":"鈴木家住宅店蔵","kana":"すずきけじゅうたくみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市中町8他","lat":36.40754365,"lng":136.44960339,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積22㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2012.02.23(平成24.02.23)","register_no":"17 - 0235","desc":"主屋北側に接して建つ蔵で、東西5.2メートル南北4.3メートル、鉄筋コンクリート造2階建、陸屋根である。外壁を漆喰塗、腰を戸室石張として土蔵風に仕上げ、パラペットの東面を山型につくりアクセントとする。大火後の再建のため防火に配慮した店蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009161"},{"id":"00011937","register_sub_id":"101","register_pk":"211085","name":"青林寺客殿（和倉御便殿本殿）","kana":"せいりんじきゃくでん（わくらごべんでんほんでん）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県七尾市和倉町レ61他","lat":37.087375,"lng":136.912737,"geo_status":"db","era":"明治42年／昭和51年移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"17-271","desc":"明治四二年の皇太子行啓に際し建てられた御便殿のうち、御座所を含む本殿部分を移築したもの。式台玄関から畳廊下を介して座敷、控之間、御座所等を配する。小屋はトラス。総檜造で、御座所の折上格天井など随所に精緻な技巧を見せる。便殿建築の希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011937"},{"id":"00014354","register_sub_id":"101","register_pk":"511343","name":"高家住宅主屋","kana":"たかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県小松市日用町寅71他","lat":36.32019167,"lng":136.46655833,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積227㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"17 - 0309","desc":"小松市南東の日用に所在する林業家の主屋。二階建切妻造妻入桟瓦葺で敷地中央に南面する。間取りは加賀地方妻入民家の典型で広大な広間と仏間を有し、各室の軸部や建具は漆塗仕上。土間や広間廻りの柱や梁に日用杉を多用し、地域の歴史を伝える豪壮な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014354"},{"id":"00014355","register_sub_id":"101","register_pk":"511344","name":"高家住宅土蔵","kana":"たかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県小松市日用町寅71他","lat":36.32013611,"lng":136.46649722,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"17 - 0310","desc":"林業家の民家主屋の西に位置する土蔵。二階建切妻造平入の東西棟を、通路を挟み東西に並べ、西を米倉、東を漬物蔵とする。二棟一体で桟瓦葺屋根を架けた長大な土蔵で、南面に下屋を一連で付し、大きな蔵前とする。内部は各階とも板敷。旧家の屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014355"},{"id":"00004136","register_sub_id":"101","register_pk":"105126","name":"多川家住宅主屋","kana":"たがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市四ツ屋町38","lat":36.488312,"lng":136.540466,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積337㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0108","desc":"加賀藩家臣も務めた旧家の住宅。木造２階建で，正面中央に式台玄関を開き，２０畳の大広間，座敷などを配する。２階には使用人のための空間等を配する。正面はアズマダチとし，特徴的な外観を見せる他，大広間の豪壮な架構などにも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004136"},{"id":"00009261","register_sub_id":"101","register_pk":"194054","name":"田辺家住宅主屋","kana":"たなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市寺町1-138","lat":36.54820939,"lng":136.65848073,"geo_status":"db","era":"昭和2年／平成22年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積100㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0238","desc":"北西角地に建つ木造二階建、寄棟造桟瓦葺で、北面に東入りの玄関、西面に平家建の茶の間浴室がつく。東面北寄りは上下階通しの出窓で、二階南半のサンルームにガラス障子を建て込む。南側は上下階とも和室で南面出窓は東面と同意匠。ホール式平面の近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009261"},{"id":"00009262","register_sub_id":"101","register_pk":"194055","name":"田辺家住宅門及び塀","kana":"たなべけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市寺町1-138","lat":36.54832483,"lng":136.65854668,"geo_status":"db","era":"昭和2年／昭和中期改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"門 コンクリート造、高さ2.9m 塀 コンクリート造、延長24m","structure_material":"門 コンクリート造","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0239","desc":"敷地東面北端に開く門で、北側門柱は高さ二・九メートルの円柱で基部は玉石張、胴部はモルタル塗で円盤が載る。南側門柱は植木鉢とする。門から南へ延びる塀はコンクリート擁壁に玉石張で、片端波形のコンクリートブロックを一段積み、南面東半まで廻らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009262"},{"id":"00004352","register_sub_id":"101","register_pk":"105342","name":"辻家住宅表門及び塀","kana":"つじけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市寺町1-8-48","lat":36.54801267,"lng":136.6587726,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造、銅板葺一部瓦葺、板塀延長42m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0118","desc":"敷地西面の道に沿って約４０ｍの小屋根付板塀を築き，中央やや南寄りに内側に控えて袖塀付腕木門を開く。塀は高いが上部に横桟を入れて開口し，門の親柱は節付きの丸太で，屋根は一部に桟瓦を置いた銅板葺とするなど軽快な意匠になり，屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004352"},{"id":"00004351","register_sub_id":"101","register_pk":"105341","name":"辻家住宅主屋","kana":"つじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市寺町1-8-48","lat":36.54814551,"lng":136.65886625,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0117","desc":"犀川下菊橋南西の台地上に建つ。平屋建，入母屋及び寄棟造，桟瓦葺で，玄関を突出した居室部とその北西に接続する茶の間・台所部から成る。良材を用いた座敷は床，棚，付書院を構え周囲に縁を廻した本格的なつくりで，壁を群青色土壁とした独特の意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004351"},{"id":"00006450","register_sub_id":"101","register_pk":"107433","name":"戸水家住宅土蔵","kana":"とみずけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市寺町二丁目63","lat":36.55000678,"lng":136.65548907,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"17 － 0165","desc":"店舗兼住宅の西方、敷地の最奧に東西棟で建つ。桁行２間半、梁間３間、切妻造、桟瓦葺、妻入の２階建土蔵で、基礎は石積、屋根は置屋根とし、東面に戸口を設ける。外部は白漆喰塗とし、西面は押縁下見板張で覆い、鉢巻や窓まわりなどに丁寧な縁取仕上げを施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006450"},{"id":"00010768","register_sub_id":"101","register_pk":"201603","name":"長沖蔵","kana":"ながおきくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県小松市安宅町タ45","lat":36.419449,"lng":136.420358,"geo_status":"db","era":"江戸末期／昭和20頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"17 ‐ 0253","desc":"安宅港で廻船問屋を営んでいた瀬戸家のもと土蔵。当初は平屋建で、昭和二〇年頃に二階の床を設けた。外壁は竪板張で、壁の下地に石板を張るという当地で散見される技法を用いる。川岸に近く、北前船で栄えた往時の安宅港の景観を伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010768"},{"id":"00010766","register_sub_id":"101","register_pk":"201601","name":"長沖金剛","kana":"ながおきこんごう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県小松市安宅町タ12","lat":36.420129,"lng":136.41947,"geo_status":"db","era":"昭和前期／昭和21移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"17 ‐ 0251","desc":"梯川河口左岸にある老舗料亭の客室棟で、入母屋造平屋建である。もと安宅港の廻船問屋であった松村家の離れを移築したもので、一六畳主室など三室を並べて広縁を通す。幅広の天井板など良材を用い、加賀らしい赤色の土壁を塗るなど、格調高い意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010766"},{"id":"00010767","register_sub_id":"101","register_pk":"201602","name":"長沖弁慶","kana":"ながおきべんけい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県小松市安宅町タ3","lat":36.420479,"lng":136.419205,"geo_status":"db","era":"昭和10／昭和54移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"17 ‐ 0252","desc":"金沢市尾山町に所在した繊維会社社長宅を移築した。二階建を東西に雁行させた平面で、東面中央に入母屋玄関を設ける。特に西棟は上下階とも二室続きの座敷に縁を廻らせ、いずれの室も数寄屋意匠を用いつつ、洗練された造作の座敷飾や欄間を備え、質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010767"},{"id":"00003416","register_sub_id":"101","register_pk":"104406","name":"長田家住宅主屋","kana":"ながたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市橋場町147","lat":36.570496,"lng":136.664963,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積206㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0078","desc":"浅野川大橋南詰近くに位置する。内科医の住居として建設された中廊下型の和洋折衷住宅で，玄関奥に洋間，中廊下の南側に居間，階段，広縁などを配する。設計施工は松井角平率いる松井組で，階段踊場のステインドグラスや化粧枠，手摺などの意匠に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003416"},{"id":"00010585","register_sub_id":"101","register_pk":"201159","name":"中西家住宅主屋","kana":"なかにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市瓢簞町165","lat":36.577153,"lng":136.658839,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積57㎡、門柱及び塀付","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"17－0250","desc":"前面道路から後退して建ち、正面右寄りに入母屋造の玄関を構え、コンクリート製の門柱及び塀で前庭を囲む。切妻造平入で軒をせがい造とし、前庭を確保する建物配置など、当地における町家建築の伝統的手法を採用しつつ、室内造作も洗練された近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010585"},{"id":"00003415","register_sub_id":"101","register_pk":"104405","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市東山1-4-33","lat":36.57301459,"lng":136.66633196,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0077","desc":"重伝建保存地区東山ひがしに近接し，城北大通りに平行する小路に東面して建つ。間口３間半規模の木造２階建，平入町家で，内部上手は１列半３室型とし，表構えは２階に袖壁を付け，１階は玄関以外を出格子窓とする。金沢城下における小規模町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003415"},{"id":"00011288","register_sub_id":"101","register_pk":"209124","name":"那谷寺普門閣","kana":"なたでらふもんかく","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県小松市那谷町ユ122-1","lat":36.31297688,"lng":136.42045049,"geo_status":"db","era":"弘化4頃／昭和40移築","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"木造2階建、銅板葺、建築面積300㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0265","desc":"那谷寺境内中央に北面して建つ。元は小松市山間部の新保地域にあった春木家住宅主屋を昭和四〇年に移築したもの。木造二階建、切妻造銅板葺妻入の大型の農家で、前広間型の平面を持ち、東列奥に豪壮な仏間を構える。木柄も太く、当地方の大規模農家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011288"},{"id":"00005601","register_sub_id":"101","register_pk":"106589","name":"南惣家住宅馬屋","kana":"なんそうけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県輪島市町野町東大野ク100","lat":37.44087975,"lng":137.06715925,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"17 － 0156","desc":"前蔵の南に建つ。東西棟の切妻造，桟瓦葺，２階建で，南面に庇を架ける。構造は真壁造で，貫を多用して堅固な軸組をつくり，１階の外壁は押縁下見板張で覆う。内部は１階を牛馬舎に細かく間仕切るが，２階は茅置場とする。大規模屋敷に相応しい規模形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005601"},{"id":"00005599","register_sub_id":"101","register_pk":"106587","name":"南惣家住宅主屋","kana":"なんそうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県輪島市町野町東大野ク100","lat":37.441239,"lng":137.06694175,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、茅葺（鉄板仮葺）、建築面積322㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"17 － 0154","desc":"東面する入母屋造の民家。もと茅葺の屋根は急勾配で，全体にたちの高いつくりであるが，四周に下屋が廻り，外観は安定感がある。欅や松等の良材を用いた丁寧なつくりで，座敷の意匠も端正で質が高い。明治期における大規模民家の特性を端的に示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005599"},{"id":"00005600","register_sub_id":"101","register_pk":"106588","name":"南惣家住宅前蔵","kana":"なんそうけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県輪島市町野町東大野ク100","lat":37.4410505,"lng":137.06719912,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積96㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"17 － 0155","desc":"主屋の東南に位置する。南北棟の切妻造，桟瓦葺，土蔵造２階建で，西面に４箇所の扉口を構え，外壁は漆喰塗，東面と西面の腰を海鼠壁とする。内部は北より米蔵，味噌蔵，納屋，使所の４室に分かれている。主屋と同時期に建てられたもので，つくりも上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005600"},{"id":"00003413","register_sub_id":"101","register_pk":"104403","name":"西家住宅主屋","kana":"にしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市長町3-1-57","lat":36.56564304,"lng":136.64917476,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積440㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0075","desc":"長町武家屋敷地区の一画に位置する。東西棟，２階建の本屋と南北棟，平屋建の座敷から成り，本屋は大野庄用水と並行する道路に東面して建つ。正面はアズマダチ風につくるが，２階はたちが高く，門を造らない屋敷構えなどにも近代和風住宅の特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003413"},{"id":"00003414","register_sub_id":"101","register_pk":"104404","name":"西家住宅土蔵","kana":"にしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市長町3-1-57","lat":36.56565417,"lng":136.6490211,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0076","desc":"主屋本屋の西方に南北棟で建つ。桁行６．７ｍ，梁間６．８ｍ規模の正方形に近い平面をもつ２階建土蔵で，屋根は桟瓦葺の置屋根とし，南側に広い蔵前を設けて本屋南西部に繋げる。南側道路に向けて南妻面上部を見せ，小路入口部の街路景観の主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003414"},{"id":"00003229","register_sub_id":"101","register_pk":"104219","name":"西田幾多郎書斎骨清窟","kana":"にしだきたろうしょさいこっせいくつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県かほく市内日角井1","lat":36.71461944,"lng":136.69376944,"geo_status":"db","era":"大正12／昭和49移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0069","desc":"哲学者西田幾多郎の住宅洋室部。桁行２間梁間３間の１２畳規模，鉄板葺，切妻造で，南面にテラスを設け，西面中央に煖炉煙突をあげる。外部は腰を橙色のタイル張，上部をドイツ壁とする。大正期のいわゆる文化住宅における応接間としての玄関脇洋館の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003229"},{"id":"00005125","register_sub_id":"101","register_pk":"106115","name":"橋本酒造石蔵","kana":"はしもとしゅぞういしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.327789,"lng":136.386307,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積26㎡","structure_material":"木骨石造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0136","desc":"道具蔵の南方に東西棟で建つ。桁行３間，梁間２間半規模の木骨石造２階建で，東面の北寄りに戸口を設ける。家財蔵で，壁の内側は板張，外側には凝灰岩の滝ヶ原石を積む。屋根は切妻造，桟瓦葺の置屋根で，主屋や離座敷等と同様に棟に凝灰岩の笏谷石を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005125"},{"id":"00005132","register_sub_id":"101","register_pk":"106122","name":"橋本酒造表門","kana":"はしもとしゅぞうおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32792484,"lng":136.38662945,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、銅板葺、間口1.7m、袖塀付","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0143","desc":"敷地東辺北寄りに，主屋北側庭園への出入口として設けられる。間口１．７ｍ，切妻造，銅板葺の１間１戸棟門で，本柱は礎石建ちとし，背面に控柱を斜めに建て，扉上の格子欄間に「開花亭」の扁額を掲げる。昭和２３年の福井地震後，同位置にほぼ同型式で再建。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005132"},{"id":"00005124","register_sub_id":"101","register_pk":"106114","name":"橋本酒造道具蔵","kana":"はしもとしゅぞうどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32789449,"lng":136.38624982,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0135","desc":"離座敷の西方に建ち，主屋とは廊下で連絡する。桁行５間半，梁間２間半，南北棟，切妻造，桟瓦葺，妻入の２階建土蔵で，南面に戸口を設け，各階北面に窓を開ける。西面及び北面と東面の北寄りに柱を密に接して建てるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005124"},{"id":"00005123","register_sub_id":"101","register_pk":"106113","name":"橋本酒造離座敷","kana":"はしもとしゅぞうはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32793814,"lng":136.38637096,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0134","desc":"主屋の北西に接続して南北棟で建つ。入母屋造，桟瓦葺の木造平屋建で，１２畳半の座敷と１０畳を南北に並べ，東面に広縁，主屋寄りの東南部に４畳半の茶室を配する。福井地震後の再建であるが，座敷は床，襖絵，折上天井等を備え，格式高いつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005123"},{"id":"00005133","register_sub_id":"101","register_pk":"106123","name":"橋本酒造塀","kana":"はしもとしゅぞうへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32778911,"lng":136.38579581,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、瓦葺、延長23m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0144","desc":"敷地東北辺に，凝灰岩石積み基礎の上に建つ。腰を縦板張，長押上を黒漆喰塗とし，桟瓦葺の屋根を架け，笏谷石の棟石を据える。東北角で曲線を描き，表門両側及び東辺南端で直角に折れ，南端は主屋の出格子窓に取り付く。表門同様，福井地震後の再建になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005133"},{"id":"00004347","register_sub_id":"101","register_pk":"105337","name":"八田家住宅主屋","kana":"はったけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市今町ル1","lat":36.63265716,"lng":136.70748855,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0113","desc":"市北部，旧北国街道から少し入った集落にある農家。間口８間奥行８間規模，切妻造，桟瓦葺で，北面出入口以外の大半を床上部とする。吟味した良材をふんだんに使った上質な建物で，たちが高く，アズマダチの大型の妻を正面に見せる姿は，周囲でも一際目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004347"},{"id":"00004348","register_sub_id":"101","register_pk":"105338","name":"八田家住宅西蔵","kana":"はったけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市今町ル1","lat":36.63257752,"lng":136.70734681,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0114","desc":"主屋西方に独立して建ち矩ね折れにのびる渡り廊下で連絡する。桁行３間梁間４間，切妻造，桟瓦葺の土蔵造２階建で，屋根は北側の平屋部分に大きく葺きおろす。簡素だが，非対称の屋根形式や軒及び螻羽を方杖で大きく持ち出すなど，変化に富んだ外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004348"},{"id":"00004349","register_sub_id":"101","register_pk":"105339","name":"八田家住宅南蔵","kana":"はったけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市今町ル1","lat":36.63252916,"lng":136.70747898,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0115","desc":"主屋の南西に隣接して建ち渡り廊下で連絡する。桁行３間半梁間２間半の土蔵造２階建で，桟瓦葺の置屋根を載せる。外壁は中塗仕上げとし基礎部も一段厚く塗り込める。小規模で簡素なつくりの土蔵だが，西蔵とともに屋敷背後の構えを整えるのに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004349"},{"id":"00004343","register_sub_id":"101","register_pk":"105333","name":"浜名家住宅主屋","kana":"はまなけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市扇町11-12","lat":36.562428,"lng":136.669586,"geo_status":"db","era":"江戸末期／大正7増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積175㎡","structure_material":"木造2階一部平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0109","desc":"もと武家屋敷が建ち並んでいた一画に建つ。通りに北面する敷地の中央に建ち，屋根は前寄り平屋建部分と後方２階建部分に棟高を変えて架ける。小屋束と貫を密に配したいわゆるアズマダチの大小の妻面を前後二重に見せた正面の構えは，周囲でも一際目立つ存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004343"},{"id":"00004344","register_sub_id":"101","register_pk":"105334","name":"浜名家住宅土蔵","kana":"はまなけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市扇町11-12","lat":36.56235284,"lng":136.66957598,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0110","desc":"主屋の南背後の西端部に建つ。桁行３間梁間２間半，土蔵造２階建で，桟瓦葺の置屋根を載せ，１階正面の戸口前に片流れの庇を付けて主屋台所と接続する。１，２階とも東面庭側にのみ小窓を開けた閉鎖的なつくりで，漆喰塗込めの装飾を配した堅牢な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004344"},{"id":"00012523","register_sub_id":"101","register_pk":"367818","name":"彦三町家","kana":"ひこそまちや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県金沢市安江町187","lat":36.574337,"lng":136.654968,"geo_status":"geocoded","era":"昭和6年頃／平成27年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡、門柱及び塀付","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"17 － 0283","desc":"市中心部の住宅地にあり、街路から後退して建つ。北を正面として前庭を設け、コンクリート造の門塀で囲む。二階建、切妻造妻入で、正面東端に台所を突出する。一階に居室、二階に客座敷を設ける。妻面のアズマダチの意匠など伝統形式を踏襲した近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012523"},{"id":"00004130","register_sub_id":"101","register_pk":"105120","name":"平木家住宅主屋","kana":"ひらきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市菊川1-363","lat":36.55078772,"lng":136.66294298,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積102㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0102","desc":"金沢城下旧足軽組地に位置する武家住宅のひとつ。南に庭を設け，西側で街路に接し，東側は用水路に面して建つ。１階は西南隅に玄関を開き，中程に仏間・茶の間を，東寄りには庭に面して縁を備える座敷と納戸を配する。２階は居室と納戸を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004130"},{"id":"00004133","register_sub_id":"101","register_pk":"105123","name":"藤本家住宅主屋","kana":"ふじもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市東山三丁目７０８他","lat":36.57503172,"lng":136.66233049,"geo_status":"db","era":"大正12／昭和8増築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0105","desc":"木造２階建の住宅。当初に建てられた平屋建の北西部分と，昭和８年に増改築された街路に面する南東部分からなる。全体にたちが高く，入母屋，寄棟が折り重なる複雑な屋根構成が外観を特徴づけている。良材を用いた，近代和風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004133"},{"id":"00002380","register_sub_id":"101","register_pk":"103370","name":"松任市ふるさと館（旧吉田家住宅）主屋","kana":"まっとうしふるさとかん（きゅうよしだけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市殿町56","lat":36.526253,"lng":136.567383,"geo_status":"db","era":"明治前期／大正1移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積449㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"17 － 0054","desc":"ＪＲ北陸本線松任駅の駅前に建つ地元実業家の邸宅。もと南方の安吉地区に所在した加賀特有の妻入民家を移築し，北妻側に移築部とは棟を直交させた片流状の屋根を架け，正面中央に入母屋造の車寄を付ける。伝統的民家の近代における増築の在り方を示す一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002380"},{"id":"00002381","register_sub_id":"101","register_pk":"103371","name":"松任市ふるさと館（旧吉田家住宅）物置一","kana":"まっとうしふるさとかん（きゅうよしだけじゅうたく）ものおきいち","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市殿町56","lat":36.526485,"lng":136.567429,"geo_status":"db","era":"大正1頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"17 － 0055","desc":"主屋の北方，敷地の北辺に位置する表門の東に建つ。東西棟，切妻造，桟瓦葺の長屋風建家で，桁行４間半，梁間２間の規模を有し，南面に入口，東端に通用門を開ける。駅前広場側の北面は，水路に沿った亀甲積石垣と木柄の太い押縁等により整った外構を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002381"},{"id":"00002382","register_sub_id":"101","register_pk":"103372","name":"松任市ふるさと館（旧吉田家住宅）物置二","kana":"まっとうしふるさとかん（きゅうよしだけじゅうたく）ものおきに","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市殿町56","lat":36.52647,"lng":136.567245,"geo_status":"db","era":"大正1頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"17 － 0056","desc":"門の西方に建つ。門東方の物置一とほぼ同様の造りになり，南面に引違格子戸と引違ガラス戸を入れるが，桁行は２間半と小さい。北面も物置一と同様に亀甲積石垣上に押縁下見の外壁をつくり，門寄りに格子窓を開ける。表構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002382"},{"id":"00002383","register_sub_id":"101","register_pk":"103373","name":"松任市ふるさと館（旧吉田家住宅）門","kana":"まっとうしふるさとかん（きゅうよしだけじゅうたく）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市殿町56","lat":36.526489,"lng":136.567337,"geo_status":"db","era":"大正1頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、銅板葺、間口2.4m、東側脇門付","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"17 － 0057","desc":"１間１戸，銅板葺の平唐門で，主屋玄関の真北からやや東に寄った位置に建つ。東方の物置一との間に銅板葺，起り屋根のやや広めの脇門を，西方の物置二との間に銅板葺，起り屋根の狭めの通用門を従える。両物置と一体となり品格ある門構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002383"},{"id":"00012901","register_sub_id":"101","register_pk":"368004","name":"まつ家別邸吉祥庵（旧米谷銀行安宅支店）","kana":"まつやべっていきっしょうあん（きゅうこめたにぎんこうあんたくしてん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県小松市安宅町ワ32甲他","lat":36.42112778,"lng":136.42138056,"geo_status":"db","era":"明治24年／明治26年・平成元年改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 290","desc":"旧安宅町の北前船主旧別邸で、銀行支店に長く使用された。通りに西面して建つ切妻造桟瓦葺の平屋建、軒出桁造で、北面に角屋で玄関を設け、正面に下屋を出す。内部は改変があるが、南面土縁付の続き間の座敷に当初の姿を残す。船主集落の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012901"},{"id":"00014799","register_sub_id":"101","register_pk":"519057","name":"三浦家住宅主屋","kana":"みうらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市東山三丁目660他","lat":36.57393611,"lng":136.66243333,"geo_status":"db","era":"昭和20年／昭和32年増築","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、瓦葺、建築面積219㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0320","desc":"東山に位置する金箔製造業者の自邸の主屋。一階応接室は洋室、二階座敷は数寄屋意匠とする和洋折衷住宅。増築した東棟は大屋兼太郎の設計で、一階座敷・仏間は長尺杉合板で天井を張り、水平を強調した欄間や建具を用いて快明な空間とする良質な近代数寄屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014799"},{"id":"00014800","register_sub_id":"101","register_pk":"519058","name":"三浦家住宅土蔵","kana":"みうらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市東山三丁目660他","lat":36.57389722,"lng":136.66223056,"geo_status":"db","era":"大正5年頃／昭和20年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0321","desc":"主屋の西に東面する家財蔵。二階建切妻造平入置屋根形式の桟瓦葺で、東面下屋を戸前とする。基礎は赤戸室石の亀甲積、外壁は漆喰塗仕上に腰石張。内部は各階板床の一室とし、小屋組は棟木に太い垂木を架ける。浅野川沿いに面して歴史的な景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014800"},{"id":"00005121","register_sub_id":"101","register_pk":"106111","name":"室木家住宅主屋","kana":"むろきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県七尾市中島町浜田耕101-1他","lat":37.11689152,"lng":136.8505909,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積455㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0132","desc":"七尾西湾に注ぐ熊木川右岸沿いの屋敷地に西面して建つ。間口９間半規模，切妻造，妻入のアズマダチ民家の系譜をひく近代和風住宅で，南方を土間，北方を床上部とし，３列に諸室を並べ，土間上部に梁組を見せる。全体的に良材を用いた上質なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005121"},{"id":"00005274","register_sub_id":"101","register_pk":"106262","name":"室木家住宅門及び塀","kana":"むろきけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県七尾市中島町浜田耕101-1他","lat":37.11684485,"lng":136.85040744,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"門 木造、瓦葺、間口4.2m、塀 木造、瓦葺、延長43m","structure_material":"門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"17 － 0147","desc":"敷地西辺に沿って建ち，塀の両端が東に折れる。門は切妻造，桟瓦葺の薬医門で，観音開きの門扉を開く。塀は凝灰岩の基礎上に建つ竪板張の塀で，腰より上を漆喰で仕上げ，桟瓦葺屋根を置く。創建時の状態を良く留め，主屋と共に豪壮な民家の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005274"},{"id":"00005431","register_sub_id":"101","register_pk":"106419","name":"本岡家住宅内門及び築地塀","kana":"もとおかけじゅうたくうちもんおよびついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市元町2-7-7","lat":36.57985591,"lng":136.66607746,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"内門 木造、瓦葺、間口2.0m、築地塀 土塀、瓦葺、延長5.4m","structure_material":"内門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0151","desc":"主屋の北側東端に隣接して建ち，間口２ｍの木造棟門の両脇に土塀を続ける。門は切妻造，桟瓦葺で，両開きの戸を開く。塀は基礎を切石積みとし，桟瓦葺屋根の土塀で，延長５．４ｍとする。主屋北側の庭と前方の空間を分け，主屋の正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005431"},{"id":"00005428","register_sub_id":"101","register_pk":"106416","name":"本岡家住宅主屋","kana":"もとおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市元町2-7-7","lat":36.579636,"lng":136.666046,"geo_status":"db","era":"明治15／明治35移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積353㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0148","desc":"敷地西寄りに建ち，桁行１１間半，梁間７間の規模で，木造２階建，切妻造，桟瓦葺とする。表構えは妻面を見せ，いわゆる東造りの形式をとり，正面に大戸を構え，持ち送りで軒を支える。内部には大きな差物が使われるなど，材質，規模，意匠共に秀でている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005428"},{"id":"00005430","register_sub_id":"101","register_pk":"106418","name":"本岡家住宅西蔵","kana":"もとおかけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市元町2-7-7","lat":36.579536,"lng":136.665955,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0150","desc":"敷地南境に近接して，主屋の南側に建つ。桁行３間半，梁間２間で，土蔵造２階建，切妻造，桟瓦葺の置屋根とする。基礎を切石積み，外壁をモルタル塗人造石仕上げとし，腰を石張りとする。戸口を主屋側に開き，主屋と廊下で連絡する。敷地及び街路の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005430"},{"id":"00005429","register_sub_id":"101","register_pk":"106417","name":"本岡家住宅東蔵","kana":"もとおかけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市元町2-7-7","lat":36.579563,"lng":136.666214,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0149","desc":"敷地南境に近接して建ち，桁行３間半，梁間２間半の規模で，土蔵造２階建，切妻造，桟瓦葺，置屋根形式とする。外壁及び腰をモルタル塗人造石仕上げとする。主屋側１，２階に窓を２箇所づつ開き，観音開きの鉄扉を付け，主屋前庭の空間をつくる配置としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005429"},{"id":"00011682","register_sub_id":"101","register_pk":"210698","name":"愛山荘石蔵","kana":"あいざんそういしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894268,"lng":136.167099,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造2階建、瓦葺、建築面積63㎡、渡廊下付","structure_material":"石造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0173","desc":"敷地内で最も南に建ち、蔵座敷と渡り廊下で繋がる。桁行九・四メートル、梁間五・七メートル、平入で、笏谷石を積み扉口や窓は鉄扉とする。内壁はモルタル仕上げとし、小屋組は中央に鉄製のトラス梁を入れ棟木を受ける。特徴ある外観を見せる石蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011682"},{"id":"00011680","register_sub_id":"101","register_pk":"210696","name":"愛山荘一の蔵","kana":"あいざんそういちのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894729,"lng":136.167042,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0171","desc":"敷地北西角に建つ桁行七・四メートル、梁間四・七メートル、妻入で、東面に蔵前を付す。内部はケヤキを用いた堅牢な造り。敷地内の南面は一、二階とも両開窓を二所開くが、街路側は北面に扉口一所のみで、軒裏まで漆喰塗と腰板壁の外壁が街路景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011680"},{"id":"00011679","register_sub_id":"101","register_pk":"210695","name":"愛山荘蔵座敷","kana":"あいざんそうくらざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894424,"lng":136.167081,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0170","desc":"主屋南西に渡り廊下で接続する。桁行八・七メートル、梁間五・九メートルの二階建土蔵で北面下屋に玄関を設ける。外壁はモルタル洗出仕上げに目地を入れ、渦の絵様の鋼製持送りで庇を受ける。内部は一階を檜を用いた上質な座敷とする。近代の蔵座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011679"},{"id":"00011677","register_sub_id":"101","register_pk":"210693","name":"愛山荘主屋","kana":"あいざんそうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894672,"lng":136.167251,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0168","desc":"武生駅南西の市街地にある。敷地北端に建ち、一階は玄関奥に前室を介して座敷二室を並べ、庭園に向けて畳縁を廻らす開放的な造り。二階は日野山を望む東面に板縁を設け、銘木を用いた座敷廻りや瀟洒な透彫りの板欄間など、近代的な趣向が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011677"},{"id":"00011683","register_sub_id":"101","register_pk":"210699","name":"愛山荘茶室","kana":"あいざんそうちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894432,"lng":136.167177,"geo_status":"db","era":"昭和3年頃／昭和後期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0174","desc":"蔵座敷の東に建つ。四畳半の茶室と廊下を介した水屋からなる。良材による瀟洒な造りで、節付の丸太材や皮付の赤松や竹を用いて野趣も加味する。障子窓を大きく開き、開放的である。蔵座敷と一体となり、端正な中にも変化に富んだ意匠を見せる茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011683"},{"id":"00011681","register_sub_id":"101","register_pk":"210697","name":"愛山荘二の蔵","kana":"あいざんそうにのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894577,"lng":136.167043,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0172","desc":"敷地の西面で街路に面する。桁行九・四メートル、梁間五・六メートル、平入で、東面に蔵前を付ける。内部は一、二階とも一室で、漆喰壁に板張とする。正面では、両開扉を五段の掛子塗とし、腰部なども黒漆喰仕上げとし、重厚な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011681"},{"id":"00011678","register_sub_id":"101","register_pk":"210694","name":"愛山荘離れ","kana":"あいざんそうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市若竹町14字天野2","lat":35.894709,"lng":136.167508,"geo_status":"db","era":"大正5年頃／昭和17年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積151㎡、渡廊下付","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0169","desc":"主屋東に廊下を介して接続する。六畳一間の「旧離れ」と一〇畳と六畳からなる「離れ」を配する。「旧離れ」は庭園側の東南面に矩折れの地袋を設け、上部をガラス窓で開放する。「離れ」は端正な造りで、床廻りに円窓を配すなど、近代的な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011678"},{"id":"00011684","register_sub_id":"101","register_pk":"210700","name":"愛山荘待合","kana":"あいざんそうまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894342,"lng":136.167166,"geo_status":"db","era":"昭和3年頃／昭和後期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積4.7㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0175","desc":"茶室の南西方に位置する。茶室に対してやや北に振り、庭への眺望を確保した配置とする。桁行三・〇メートルで招造屋根とし、腰掛の後ろに下屋を付ける。主に丸太を用い、袖壁には下地窓を設けるなど、数寄屋風意匠を見せ、露地空間を良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011684"},{"id":"00011685","register_sub_id":"101","register_pk":"210701","name":"愛山荘門及び塀","kana":"あいざんそうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市若竹町14字天野1-4","lat":35.894667,"lng":136.167015,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m、左右袖塀付 塀 木造、瓦葺、延長6.2m","structure_material":"門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"18 - 0176","desc":"一の蔵と二の蔵の間に建ち、敷地西面を画す門と塀。門は、間口一・八メートルの腕木門で、引分けの板戸と格子戸を建て込む。楣上に格子欄間を入れ、垂木は吹寄せとし瀟洒な意匠を見せる。塀は真壁で外側は板張、内側は杉皮張とし、景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011685"},{"id":"00015179","register_sub_id":"101","register_pk":"530603","name":"赤井家住宅主屋","kana":"あかいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県吉田郡永平寺町清水8字村下出39","lat":36.07871111,"lng":136.4002,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積412㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0249","desc":"九頭竜川の中流域に位置する旧家の主屋。広大な敷地中央に南面して建つ二階建切妻造妻入桟瓦葺で、東に角屋を延ばす。内部は西面の式台から北東隅の主座敷に至り、縁を介して池を配した庭園を望む。束と貫を整然と組んだ妻面をみせ、大規模で風格備えた民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015179"},{"id":"00015182","register_sub_id":"101","register_pk":"530606","name":"赤井家住宅物置","kana":"あかいけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町清水8字村下出39","lat":36.07841944,"lng":136.400275,"geo_status":"db","era":"昭和18年","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積51㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0252","desc":"主屋の南東に位置する物置。２階建切妻造で北面に一間幅の下屋を付す。１階は土間で車庫と物置。二階は一室の板敷で物置とし、南西隅に荷揚口を開ける。小屋組は折置組で登梁形式と束立を併用した和小屋。旧家の日常生活を伝え、屋敷南東の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015182"},{"id":"00005832","register_sub_id":"101","register_pk":"106818","name":"石田家住宅蔵座敷","kana":"いしだけじゅうたくくらざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市川尻町33-87","lat":36.145451,"lng":136.093536,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"18 － 0046","desc":"主屋の東面南寄りに接続する土蔵造２階建。明治初期建設の酒蔵古材を利用して建設。桁行５間，梁間４間規模の南北棟で，切妻造，桟瓦葺とし，東面に土縁がつく。軒先は白漆喰塗，外壁を押縁下見板張とする。１階は１２畳を中心とした座敷，２階は物入とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005832"},{"id":"00005831","register_sub_id":"101","register_pk":"106817","name":"石田家住宅主屋","kana":"いしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県福井市川尻町33-87","lat":36.14542781,"lng":136.09337348,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"18 － 0045","desc":"敷地の中央に南面して建つ木造平屋建で，桁行１０間半，梁間６間半の規模とする。切妻造の妻入で，越前赤瓦の桟瓦葺とする。正面は，妻面を梁と束を見せる真壁造の白漆喰塗とし，瓦葺庇がつく。間取りは南半を土間と板敷とし，北半に畳敷の諸室を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005831"},{"id":"00005834","register_sub_id":"101","register_pk":"106820","name":"石田家住宅長屋門","kana":"いしだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県福井市川尻町33-87","lat":36.145184,"lng":136.093582,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"18 － 0047","desc":"敷地の南正面に建つ桁行１２間半，梁間２間半の木造平屋建で，入母屋造，桟瓦葺とする。桁行ほぼ中央の３間を門とし，間口１０尺の門柱に両開の門扉を釣込み，西側に潜戸を設ける。外壁は白漆喰塗で，表側に小さな格子窓を開き，腰を押縁下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005834"},{"id":"00005837","register_sub_id":"101","register_pk":"106823","name":"石田家住宅西蔵","kana":"いしだけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県福井市川尻町33-87","lat":36.14527879,"lng":136.09333421,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"18 － 0049","desc":"敷地西辺の前蔵の北に並んで建つ桁行４間，梁間２間半の土蔵造２階建で，切妻造，桟瓦葺とする。東面と南面に戸口を設ける。外壁は白漆喰塗で押縁下見板張とする。東面には南から桁行３間，梁間１間半の味噌多聞と呼ぶ土蔵造下屋がつき，東面を海鼠壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005837"},{"id":"00005836","register_sub_id":"101","register_pk":"106822","name":"石田家住宅前蔵","kana":"いしだけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県福井市川尻町33-87","lat":36.145218,"lng":136.093414,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"18 － 0048","desc":"敷地の西辺南寄りに位置する桁行５間，梁間２間半の土蔵造２階建で，切妻造，桟瓦葺とし，棟に笏谷石を載せる。東面に１間半幅の瓦葺庇をつけて蔵前としている。軒回りを白漆喰塗とし，外壁に押縁下見板を張る。小屋組は梁上に束立で地棟と母屋を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005836"},{"id":"00004746","register_sub_id":"101","register_pk":"105736","name":"魚志楼（松崎家住宅）奥座敷","kana":"うおしろう（まつざきけじゅうたく）おくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県坂井市三国町神明3-43","lat":36.21610134,"lng":136.14483534,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0040","desc":"奥行の深い宅地の最奥に位置し廊下で連絡する。２階建，切妻造，桟瓦葺で，１，２階に座敷を取り，１階南，西折れ廻りに土間を配す。全体に木割が細く内法上小壁に扇面形の開口を設けるなど意匠を凝らし，土間を介し庭と融合した瀟洒な数寄屋風の座敷となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004746"},{"id":"00004743","register_sub_id":"101","register_pk":"105733","name":"魚志楼（松崎家住宅）主屋","kana":"うおしろう（まつざきけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市三国町神明3-43","lat":36.21621707,"lng":136.14473217,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0037","desc":"切妻造妻入の主体部の前方に平入の表屋を付けた「かぐら建て」の町家。間口３間半，奥行６間半，２階建，桟瓦葺で，表に店，右手に通り庭（板間に改造），これに沿って座敷を並べる。小規模だが袖壁を付けたたちの低い外観は往時の湊町の賑わいをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004743"},{"id":"00004744","register_sub_id":"101","register_pk":"105734","name":"魚志楼（松崎家住宅）西蔵","kana":"うおしろう（まつざきけじゅうたく）にしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市三国町神明3-43","lat":36.21617103,"lng":136.14480124,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建、瓦葺、建築面積35㎡","structure_material":"土蔵造２階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0038","desc":"主屋の南西，西に突出した敷地に建つ。桁行３間半，梁間２間半，２階建，土蔵造，切妻造，桟瓦葺で，主屋から奥座敷に至る長い渡り廊下に接する東妻側に戸口を開く。重厚な構成を利用しつつ，内部が床，棚を備えた座敷に改造され料亭の客室として活用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004744"},{"id":"00004745","register_sub_id":"101","register_pk":"105735","name":"魚志楼（松崎家住宅）東蔵","kana":"うおしろう（まつざきけじゅうたく）ひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市三国町神明3-43","lat":36.21612738,"lng":136.14472582,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積29㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0039","desc":"主屋と奥座敷の間に位置し，矩折れに続く長い渡り廊下の途中に接して建つ。桁行２間半余，梁間２間，平屋，土蔵造，切妻造，桟瓦葺で，南面に下屋を葺き下ろし戸口を開く。小規模だが内外とも入念な造りで，内部は座敷に改造され料亭の客室として活用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004745"},{"id":"00012329","register_sub_id":"101","register_pk":"531653","name":"越前古窯博物館旧水野九右衛門家住宅（旧水野家住宅主屋）","kana":"えちぜんこようはくぶつかんみずのくうえもんけじゅうたく（きゅうみずのけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県丹生郡越前町小曽原107-1-169","lat":35.93617222,"lng":136.059375,"geo_status":"db","era":"天保6年(1835)／明治中期改修、平成29年移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"18-193","desc":"山村集落からの移築民家。切妻造妻入の正面左右に突出部を設ける、いわゆる両袖造の形式とする。外観は真壁造の漆喰仕上で腰板張。内部は正面に土間と板間、その奥に整形四間取で居室を並べ、背面に仏間上段と納戸を張出す。当地の上層農家の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012329"},{"id":"00008854","register_sub_id":"101","register_pk":"162297","name":"大橋家住宅表門","kana":"おおはしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市石田上町38字南ノ町20他","lat":35.97537451,"lng":136.1623224,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、銅板葺、間口2.1m、左右潜戸付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0108","desc":"敷地東辺中央、通りに面して建つ。門口2.1メートルの冠木門を基本とし、左右に脇柱を立てて潜戸を吊り、本柱の背後に控え柱を添えて、親柱の頂部や冠木などの上に、銅板葺の切妻屋根をかける。通常の形式とは異なる独創的な門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008854"},{"id":"00008852","register_sub_id":"101","register_pk":"162295","name":"大橋家住宅主屋","kana":"おおはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市石田上町38字南ノ町20他","lat":35.97555267,"lng":136.16208624,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0106","desc":"敷地中央に建ち、木造2階建、建築面積201平方メートル、切妻造桟瓦葺の上屋の周囲に下屋が付く。床上部は六間取とし、ホンザシキは長押を廻らして透彫欄間を飾り、仏間には格天井を張るなど整った室内意匠をもつ。越前地方における大規模民家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008852"},{"id":"00008853","register_sub_id":"101","register_pk":"162296","name":"大橋家住宅土蔵","kana":"おおはしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市石田上町38字南ノ町20他","lat":35.97551124,"lng":136.16228304,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0107","desc":"主屋の東側に位置する。東西棟とする切妻造桟瓦葺で，桁行7.6メートル梁間4.8メートルの土蔵造二階建。西側に蔵前を附属し、東西面にそれぞれ出入口を設け、南北面に窓を穿つ。外部の腰高に張られた簓子下見板が風情のある屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008853"},{"id":"00012145","register_sub_id":"101","register_pk":"352944","name":"尾崎家住宅表門","kana":"おざきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市寺中町21字下出11","lat":35.957518,"lng":136.288647,"geo_status":"db","era":"文政4年(1821)／平成8年改修","year":1821,"year_source":"db","year_min":1821,"year_max":1821,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀及び南方潜戸付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"18-185","desc":"主屋の正面に西面して建つ。間口二・七メートルの一間薬医門で、屋根は切妻造、桟瓦葺。両脇に袖塀を付け南側に潜戸を開く。ケヤキ材を用い堅実な造りの表門であり、板扉には四葉金具を打ち、風格を備えた表構えで屋敷を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012145"},{"id":"00012144","register_sub_id":"101","register_pk":"352943","name":"尾崎家住宅主屋","kana":"おざきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市寺中町21字下出11","lat":35.957556,"lng":136.288865,"geo_status":"db","era":"江戸後期／明治後期・昭和40年代・平成8年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積250㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"18-184","desc":"前広間型平面の近世民家で、広間には梁組を現すオウエを中心として両脇に突出部を付け、奥はもと二列六室で僧侶のための休息の間を備える。本座敷のみ長押を廻らし、他は差鴨居に付樋端と古式である。茅葺から瓦葺への変遷を示す痕跡を留めており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012144"},{"id":"00014483","register_sub_id":"101","register_pk":"513897","name":"木下家住宅表門","kana":"きのしたけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県丹生郡越前町栃川24字辻本5-2","lat":35.98844722,"lng":136.12714444,"geo_status":"db","era":"明治20年頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造、瓦葺、間口2.4m、袖塀付","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0242","desc":"主屋の南に位置する薬医門。切妻造桟瓦葺で両袖に板塀を付し、いずれも引戸の潜戸を開ける。角柱の親柱と控柱を貫で固め、肘木で受けた梁上に束を立てて棟木を受け、軒は一軒繁垂木とする。両袖塀の絵振板を彫刻で飾り、簡素ながらも旧家の風格を示す薬医門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014483"},{"id":"00014482","register_sub_id":"101","register_pk":"513896","name":"木下家住宅主屋","kana":"きのしたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県丹生郡越前町栃川24字辻本4-2他","lat":35.98863333,"lng":136.12716667,"geo_status":"db","era":"明治15年／同20年移築、昭和50年頃改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0241","desc":"越前町北東の山間部に所在する旧家の主屋。つし2階建、切妻造妻入桟瓦葺で南西に入母屋造式台玄関を付す。内部南側は上部に太い梁組を現す吹抜の板の間、北側に二列五室を配し北東を床構え付座敷とする。南妻を軒まで塗込めて漆喰塗で仕上げ、重厚に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014482"},{"id":"00007488","register_sub_id":"101","register_pk":"108470","name":"旧右近家住宅西洋館","kana":"きゅううこんけじゅうたくせいようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県南条郡南越前町河野2字南ノ町36他","lat":35.82571024,"lng":136.06853818,"geo_status":"db","era":"昭和10／平成元改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積129㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0080","desc":"日本海に臨む高台に建つ。ＲＣ造２階建で南側に平屋を張り出し、建築面積１２９㎡。１階は粗い仕上げのクリーム色壁面を基調としたスパニッシュ風、２階は丸太を外装材に用いるシャレー風とし、張り出した部分までスペイン瓦葺の屋根を葺き降ろす瀟洒な洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007488"},{"id":"00012326","register_sub_id":"101","register_pk":"531650","name":"旧内山家住宅衣装蔵","kana":"きゅううちやまけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大野市城町10-7","lat":35.98541667,"lng":136.48661389,"geo_status":"db","era":"明治15年頃／平成5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"18-190","desc":"味噌蔵の南東方に建つ。土蔵造二階建、切妻造桟瓦葺、外壁漆喰仕上の腰板張とする。北面中央部に戸口と蔵前を設け、両妻面に窓を開き、開口部には漆喰塗の額縁を施して丁寧に仕上げる。方杖で深い軒を支えるなど豪雪地に適応した伝統的なつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012326"},{"id":"00012327","register_sub_id":"101","register_pk":"531651","name":"旧内山家住宅米蔵","kana":"きゅううちやまけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大野市城町10-7","lat":35.98536667,"lng":136.48653889,"geo_status":"db","era":"明治15年頃／平成5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積30㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"18-191","desc":"敷地南西隅に建つ。土蔵造平屋建、切妻造桟瓦葺、外壁漆喰仕上の腰板張で、深い軒を頬杖で支える。西妻面に戸口を設けて下屋をかけ、中央部に窓を穿つ。道路に面した敷地角にあって、旧家の表構えを構成するとともに歴史的な街路景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012327"},{"id":"00012323","register_sub_id":"101","register_pk":"531647","name":"旧内山家住宅主屋","kana":"きゅううちやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大野市城町10-7","lat":35.98563611,"lng":136.48672778,"geo_status":"db","era":"明治15年頃／平成4年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"18-187","desc":"旧大野城下の武家屋敷地にあり、敷地中央に南面して建つ。切妻造平入で四周に下屋を廻す。一階は西半を板床のニワと台所とし、東半に田字型の八畳四室と奥に六畳を配する。正面の式台玄関、長押を廻して棹縁天井を張る上手の座敷など、近世の格式を継承する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012323"},{"id":"00012324","register_sub_id":"101","register_pk":"531648","name":"旧内山家住宅離れ","kana":"きゅううちやまけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県大野市城町10-7","lat":35.98547778,"lng":136.48686667,"geo_status":"db","era":"大正後期／平成4年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"18-188","desc":"主屋の南東方に渡廊下で接続する。南北棟の切妻造桟瓦葺。南に八畳座敷、北に六畳や三畳を配し、東に浴室や便所を設ける。赤松丸太の床柱を斜めに入れた奥行ある床構えや庭園側の開放的で軒の深い土庇など、伝統形式の中に近代らしいつくりを随所に用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012324"},{"id":"00012325","register_sub_id":"101","register_pk":"531649","name":"旧内山家住宅味噌蔵","kana":"きゅううちやまけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大野市城町10-7","lat":35.9855,"lng":136.48655833,"geo_status":"db","era":"明治15年頃／平成5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"18-189","desc":"土蔵造二階建、切妻造桟瓦葺で、門の南側に建つ。外壁は腰板壁、上部漆喰塗で、母屋や垂木を現す。東面北端に戸口と下屋を設け、南妻面に小窓を上下に開くのみの閉鎖的な構えである。食糧の保管に使用された蔵の一つで、伝統的な屋敷構えに欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012325"},{"id":"00012328","register_sub_id":"101","register_pk":"531652","name":"旧内山家住宅門","kana":"きゅううちやまけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大野市城町10-7","lat":35.98558611,"lng":136.48655278,"geo_status":"db","era":"明治15年頃／平成5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"18-192","desc":"敷地南西隅に建つ。土蔵造平屋建、切妻造桟瓦葺、外壁漆喰仕上の腰板張で、深い軒を頬杖で支える。西妻面に戸口を設けて下屋をかけ、中央部に窓を穿つ。道路に面した敷地角にあって、旧家の表構えを構成するとともに歴史的な街路景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012328"},{"id":"00004750","register_sub_id":"101","register_pk":"105740","name":"旧岸名家住宅主屋","kana":"きゅうきしなけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県坂井市三国町北本町4-6-54","lat":36.21387266,"lng":136.14876204,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0044","desc":"切妻造妻入の主体部の前方に平入の表屋を付けた「かぐら建て」の町家。間口５間余，奥行６間半，２階建，桟瓦葺で，室内は天井が低く柱や造作材を弁柄塗，壁を色土壁とした瀟洒な造り。表屋が北に延び変化に富んだ外観を呈し，角地に建ち周囲でも一際目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004750"},{"id":"00008454","register_sub_id":"101","register_pk":"134850","name":"旧根岸家住宅表門","kana":"きゅうねぎしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市岩本町16字中町8-1","lat":35.90850533,"lng":136.24851556,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口3.9m、便所付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0089","desc":"水路に架かる橋を介して通りに面する。間口三・九メートル、切妻造桟瓦葺で、北側に便所を付設。両端に方柱をたて、差物で固め、腕木を前後に出し、軒桁をもち出し、一軒疎垂木の軒を支持。北半部を板壁とし、板戸を引き込む。屋敷正面を画する簡易な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008454"},{"id":"00008452","register_sub_id":"101","register_pk":"134848","name":"旧根岸家住宅主屋","kana":"きゅうねぎしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市岩本町16字中町8-1","lat":35.90849728,"lng":136.24866848,"geo_status":"db","era":"明治前期／大正7年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積229㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0087","desc":"今立の町並みに位置する。敷地の中央に西面して建つ。正面一六メートル奥行一八メートル、切妻造妻入桟瓦葺の木造二階建。前寄りに土間、奥に床上部を設け、最奥にトコや仏壇を構える。正・背面に大きなウダツをたてるなど、地域的な特色が顕著な民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008452"},{"id":"00008453","register_sub_id":"101","register_pk":"134849","name":"旧根岸家住宅土蔵","kana":"きゅうねぎしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市岩本町16字中町8-1","lat":35.9084345,"lng":136.24884071,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積90㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0088","desc":"主屋後方、敷地の東端に南北棟で建つ。桁行一二メートル梁間五・九メートルと規模の大きい二階建土蔵。切妻造桟瓦葺。西面は全面に庇を付け、腰モルタルの漆喰仕上げ。その他は高く下見板を張る。内部は一、二階とも南北二室に分け、真壁で柱や貫を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008453"},{"id":"00013990","register_sub_id":"101","register_pk":"508250","name":"旧古川屋惣兵衛住宅","kana":"きゅうふるかわやそうべえじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県小浜市湊7号西湊8","lat":35.51090833,"lng":135.75018333,"geo_status":"db","era":"慶応元年(1865)","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"18 - 0232","desc":"旧小浜城下で廻船業を営んだ商家。木造二階建、切妻造桟瓦葺平入で、通りに面して出格子を設ける。二階は真壁に格子窓を嵌め、両端の袖壁から側壁を漆喰で塗込める。背面にも袖壁を備える。内部は通り土間と一列三室の平面。小浜に希少な江戸期に遡る町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013990"},{"id":"00007350","register_sub_id":"101","register_pk":"108332","name":"旧山川家住宅（山川登美子記念館）表門","kana":"きゅうやまかわけじゅうたく（やまかわとみこきねんかん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種1-16-52","lat":35.498665,"lng":135.747192,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口3.5m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0067","desc":"敷地北辺の東端、通りから４段の石段を上った位置に建つ。三間一戸棟門で、桟瓦葺の切妻屋根をかける。中央を門口とし、引分け戸をたて込む。両脇に桟瓦葺の袖塀を付ける。延長５．１ｍ。土台に柱を建て、腕木が軒を支え、壁は漆喰仕上げ腰下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007350"},{"id":"00007347","register_sub_id":"101","register_pk":"108329","name":"旧山川家住宅（山川登美子記念館）主屋","kana":"きゅうやまかわけじゅうたく（やまかわとみこきねんかん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種1-16-52","lat":35.498508,"lng":135.747086,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積173㎡","structure_material":"木造平屋一部2階建","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0064","desc":"敷地中央に東西棟で建つ。緩い起りの切妻造妻入桟瓦葺、木造平屋建で、背面側西半部を２階建とする。正面は間口５間半で、南寄りに入母屋造式台、北側は庇を設け、南面前寄りに入母屋造桟瓦葺の座敷を付ける。妻面には束や貫を現し、風格ある正面構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007347"},{"id":"00007351","register_sub_id":"101","register_pk":"108333","name":"旧山川家住宅（山川登美子記念館）中門","kana":"きゅうやまかわけじゅうたく（やまかわとみこきねんかん）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種1-16-52","lat":35.498615,"lng":135.747177,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口1.5m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0068","desc":"表門から主屋玄関への通路の西側で、主屋北庭へ開いて建つ。一間腕木門。間口１．５ｍに方柱を建て、石柱を控えとする。楣で固め、その上には襷を掛ける。屋根は切妻造で、塀瓦を葺き、棟に丸瓦を置く。庭園への入口に建つ、規模の小さい簡易な門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007351"},{"id":"00007349","register_sub_id":"101","register_pk":"108331","name":"旧山川家住宅（山川登美子記念館）土蔵","kana":"きゅうやまかわけじゅうたく（やまかわとみこきねんかん）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種1-16-52","lat":35.49866186,"lng":135.747009,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0066","desc":"敷地北西に南北に妻を見せて建つ。桁行６．８ｍ梁間５．４ｍの土蔵造２階建に切妻造桟瓦葺屋根が載り、南面に下屋庇を設け蔵前をつくる。外壁は漆喰仕上げで、竪板を高く張り、北妻面と東面に窓を穿ち、片開の鉄扉と小庇を付ける。屋敷構えを構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007349"},{"id":"00007348","register_sub_id":"101","register_pk":"108330","name":"旧山川家住宅（山川登美子記念館）離れ","kana":"きゅうやまかわけじゅうたく（やまかわとみこきねんかん）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種1-16-52","lat":35.49847952,"lng":135.74694966,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0065","desc":"主屋の南西に接して建つ。南北棟の切妻造桟瓦葺で、主室八畳を南に、次の間三畳を北に配し、三方に榑縁をまわす。縁を介して西面に東西棟の切妻造桟瓦葺の台所を付ける。主室南面にはトコと書院を並べる独特の構えをつくる。近代における良質な座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007348"}];
